import 'dart:convert';

import '../models/exercise.dart';

/// Full 151-exercise catalog, embedded from the real seeded data
/// (tools/exercise_seed/exercises_seed.json, generated from
/// tools/exercise_seed/data/*.json -- the actual source of truth already
/// pushed to Firestore). Used by InMemoryExerciseRepository so the app is
/// demoable offline without Firebase configured. If tools/exercise_seed/
/// data changes, regenerate: node tools/exercise_seed/scripts/build-seed.mjs
/// then node tools/exercise_seed/scripts/gen-flutter-fixture.mjs
final List<Exercise> sampleExercises = (jsonDecode(_rawExercisesJson) as List)
    .cast<Map<String, dynamic>>()
    .map((raw) => Exercise.fromMap(raw['id'] as String, raw))
    .toList();

const String _rawExercisesJson = r'''
[{"id":"nhon-got-dung-ta-don","name":"Nhón gót đứng tạ đơn","primaryMuscle":"bap_chan","secondaryMuscles":[],"equipment":["ta_don"],"difficulty":"beginner","instructions":["Đứng thẳng, mỗi tay cầm tạ đơn, mũi chân đứng trên bục thấp hoặc sàn phẳng.","Nhón gót lên cao hết mức có thể.","Giữ 1 giây ở điểm cao nhất, siết chặt bắp chân.","Hạ gót xuống từ từ, cảm nhận căng nhẹ ở bắp chân."],"commonMistakes":["Nhón lên quá nhanh dùng đà thay vì kiểm soát.","Không hạ hết gót xuống giữa các lần lặp, cắt ngắn biên độ."],"quickTip":"Đứng trên bục thấp để tăng biên độ chuyển động, giúp bắp chân căng giãn nhiều hơn.","suggestedRestSeconds":45,"imageUrl":"https://images.pexels.com/photos/4587372/pexels-photo-4587372.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nhon-got-dung-tren-may","name":"Nhón gót đứng trên máy","primaryMuscle":"bap_chan","secondaryMuscles":[],"equipment":["may_tap_chan"],"difficulty":"beginner","instructions":["Đứng vào máy, vai tựa vào đệm, mũi chân đặt trên bệ, gót chân treo tự do.","Nhón gót lên cao hết mức có thể.","Giữ 1 giây ở điểm cao nhất.","Hạ gót xuống thấp hơn mặt bệ để kéo giãn bắp chân trước khi lặp lại."],"commonMistakes":["Gập gối trong lúc nhón gót thay vì giữ chân thẳng.","Nhón quá nhanh liên tục không kiểm soát."],"quickTip":"Máy cho phép tập với tạ nặng hơn tạ đơn, phù hợp khi bắp chân đã quen bài tập cơ bản.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/3775599/pexels-photo-3775599.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nhon-got-ngoi-tren-may","name":"Nhón gót ngồi trên máy","primaryMuscle":"bap_chan","secondaryMuscles":[],"equipment":["may_tap_chan"],"difficulty":"beginner","instructions":["Ngồi vào máy, đặt đệm chặn lên đùi ngay trên gối.","Mũi chân đặt trên bệ, gót chân treo tự do.","Nhón gót lên cao hết mức có thể.","Hạ gót xuống thấp để kéo giãn bắp chân trước khi lặp lại."],"commonMistakes":["Đặt đệm chặn sai vị trí gây khó chịu ở đầu gối.","Nhón không hết biên độ, cắt ngắn chuyển động."],"quickTip":"Tư thế ngồi nhắm nhiều hơn vào phần bắp chân bên trong (soleus) so với đứng.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/3768183/pexels-photo-3768183.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nhon-got-khong-ta","name":"Nhón gót không tạ","primaryMuscle":"bap_chan","secondaryMuscles":[],"equipment":["khong_dung_cu"],"difficulty":"beginner","instructions":["Đứng thẳng, hai chân rộng bằng hông, có thể vịn nhẹ vào tường hoặc ghế để giữ thăng bằng.","Nhón gót lên cao hết mức có thể.","Giữ 1 giây ở điểm cao nhất.","Hạ gót xuống từ từ về vị trí ban đầu."],"commonMistakes":["Nhún gối để lấy đà thay vì nhón bằng lực bắp chân.","Thực hiện quá nhanh, không giữ ở điểm cao nhất."],"quickTip":"Bài tập cơ bản phù hợp làm khởi động hoặc tập tại nhà không cần dụng cụ.","suggestedRestSeconds":30,"imageUrl":"https://images.pexels.com/photos/4803714/pexels-photo-4803714.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nhon-got-mot-chan","name":"Nhón gót một chân","primaryMuscle":"bap_chan","secondaryMuscles":[],"equipment":["khong_dung_cu"],"difficulty":"intermediate","instructions":["Đứng thẳng trên một chân, chân kia co nhẹ ra sau, vịn nhẹ vào tường để giữ thăng bằng.","Nhón gót chân trụ lên cao hết mức có thể.","Giữ 1 giây ở điểm cao nhất.","Hạ gót xuống từ từ, hoàn thành hiệp rồi đổi chân."],"commonMistakes":["Dựa quá nhiều vào tay vịn làm giảm tải lên bắp chân.","Mất thăng bằng do nhón quá nhanh."],"quickTip":"Bài tập một chân giúp phát hiện mất cân bằng sức mạnh giữa hai bên bắp chân.","suggestedRestSeconds":45,"imageUrl":"https://images.pexels.com/photos/7298422/pexels-photo-7298422.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nhon-got-tren-may-day-dui","name":"Nhón gót trên máy đẩy đùi","primaryMuscle":"bap_chan","secondaryMuscles":[],"equipment":["may_tap_chan"],"difficulty":"beginner","instructions":["Ngồi vào máy đẩy đùi, đặt mũi chân lên mép dưới bệ đẩy, gót chân treo tự do.","Duỗi chân gần thẳng như khi đẩy đùi bình thường, giữ nguyên vị trí.","Nhón mũi chân đẩy bệ ra xa thêm bằng lực bắp chân.","Hạ gót xuống từ từ để kéo giãn bắp chân trước khi lặp lại."],"commonMistakes":["Gập gối trong lúc nhón thay vì giữ chân cố định.","Đặt mũi chân quá cao hoặc quá thấp trên bệ."],"quickTip":"Tận dụng máy đẩy đùi sẵn có để tập bắp chân mà không cần đổi máy.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/6844939/pexels-photo-6844939.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nhon-got-ta-don","name":"Nhón gót tạ đòn","primaryMuscle":"bap_chan","secondaryMuscles":[],"equipment":["ta_doi"],"difficulty":"intermediate","instructions":["Đặt thanh đòn lên lưng trên như tư thế squat, đứng thẳng, mũi chân trên bục thấp nếu có.","Nhón gót lên cao hết mức có thể.","Giữ 1 giây ở điểm cao nhất.","Hạ gót xuống từ từ về vị trí ban đầu."],"commonMistakes":["Mất thăng bằng khi đứng trên bục với tạ nặng trên vai.","Nhón không đều hai bên chân."],"quickTip":"Chỉ nên thêm tạ đòn khi đã kiểm soát tốt các biến thể nhón gót không tạ hoặc tạ đơn.","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/5837263/pexels-photo-5837263.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nhon-got-bang-day-khang-luc","name":"Nhón gót bằng dây kháng lực","primaryMuscle":"bap_chan","secondaryMuscles":[],"equipment":["day_khang_luc"],"difficulty":"beginner","instructions":["Ngồi trên sàn, chân duỗi thẳng, quấn dây kháng lực quanh lòng bàn chân.","Hai tay giữ hai đầu dây, giữ dây căng vừa phải.","Đẩy mũi chân xuống (nhón gót) đẩy dây căng ra.","Trả chân về vị trí ban đầu từ từ."],"commonMistakes":["Gập gối trong lúc đẩy mũi chân xuống.","Dùng dây quá lỏng làm giảm lực cản."],"quickTip":"Bài tập tiện lợi để tập bắp chân khi ngồi làm việc hoặc xem TV.","suggestedRestSeconds":45,"imageUrl":"https://images.pexels.com/photos/6516206/pexels-photo-6516206.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nhay-day","name":"Nhảy dây","primaryMuscle":"bap_chan","secondaryMuscles":["dui_truoc"],"equipment":["khong_dung_cu"],"difficulty":"beginner","instructions":["Đứng thẳng, cầm hai đầu dây nhảy, khuỷu tay sát thân người.","Xoay cổ tay để dây quay qua đầu và xuống dưới chân.","Bật nhảy nhẹ bằng mũi chân đúng lúc dây chạm sàn.","Giữ nhịp đều, tiếp đất êm bằng mũi chân."],"commonMistakes":["Nhảy quá cao gây mỏi chân nhanh và dễ vướng dây.","Tiếp đất bằng cả bàn chân gây áp lực lên khớp gối và mắt cá."],"quickTip":"Bắt đầu với nhịp chậm để làm quen phối hợp tay và chân trước khi tăng tốc độ.","suggestedRestSeconds":45,"imageUrl":"https://images.pexels.com/photos/4945535/pexels-photo-4945535.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"gap-bung-crunch","name":"Gập bụng (Crunch)","primaryMuscle":"bung","secondaryMuscles":[],"equipment":["khong_dung_cu"],"difficulty":"beginner","instructions":["Nằm ngửa, gối gập, hai bàn chân đặt sát sàn, tay đặt sau đầu hoặc bắt chéo trước ngực.","Siết bụng, nâng vai và lưng trên khỏi sàn.","Giữ 1 giây ở điểm cao nhất, không kéo cổ bằng tay.","Hạ người xuống từ từ về vị trí ban đầu."],"commonMistakes":["Kéo cổ bằng tay để nâng người lên thay vì dùng lực bụng.","Nâng cả lưng dưới khỏi sàn thay vì chỉ lưng trên."],"quickTip":"Thở ra khi gập lên, hít vào khi hạ xuống để tăng hiệu quả siết cơ bụng.","suggestedRestSeconds":45,"imageUrl":"https://images.pexels.com/photos/6516225/pexels-photo-6516225.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"gap-bung-cheo-bicycle-crunch","name":"Gập bụng chéo (Bicycle Crunch)","primaryMuscle":"bung","secondaryMuscles":[],"equipment":["khong_dung_cu"],"difficulty":"intermediate","instructions":["Nằm ngửa, tay đặt sau đầu, hai chân nâng lên gối gập 90 độ.","Xoay người đưa khuỷu tay phải chạm gối trái, đồng thời duỗi chân phải thẳng.","Đổi bên liên tục, khuỷu tay trái chạm gối phải.","Giữ nhịp thở đều, không kéo cổ bằng tay."],"commonMistakes":["Kéo cổ bằng tay khi xoay người.","Thực hiện quá nhanh làm giảm biên độ xoay."],"quickTip":"Tập trung xoay từ vùng bụng chứ không phải chỉ đưa khuỷu tay tới gần gối.","suggestedRestSeconds":45,"imageUrl":"https://images.pexels.com/photos/7721988/pexels-photo-7721988.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"plank","name":"Plank","primaryMuscle":"bung","secondaryMuscles":["lung_duoi"],"equipment":["khong_dung_cu"],"difficulty":"beginner","instructions":["Chống hai khuỷu tay và mũi chân xuống sàn, cơ thể tạo đường thẳng từ đầu đến gót chân.","Siết chặt bụng và mông để giữ thân người ổn định.","Giữ tư thế theo thời gian quy định, thở đều.","Không để hông võng xuống hoặc nhô cao trong suốt bài tập."],"commonMistakes":["Để hông võng xuống làm cong lưng dưới.","Nín thở thay vì thở đều khi giữ tư thế."],"quickTip":"Giữ đúng tư thế trong thời gian ngắn hiệu quả hơn giữ sai tư thế lâu.","suggestedRestSeconds":45,"imageUrl":"https://images.pexels.com/photos/4047105/pexels-photo-4047105.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"plank-nghieng-side-plank","name":"Plank nghiêng (Side Plank)","primaryMuscle":"bung","secondaryMuscles":["lung_duoi"],"equipment":["khong_dung_cu"],"difficulty":"intermediate","instructions":["Nằm nghiêng một bên, chống một khuỷu tay xuống sàn ngay dưới vai.","Nâng hông lên cao, cơ thể tạo đường thẳng từ đầu đến chân.","Giữ tư thế theo thời gian quy định, siết chặt vùng bụng bên hông.","Hạ hông xuống, hoàn thành thời gian rồi đổi bên."],"commonMistakes":["Để hông chùng xuống thấp hơn vai.","Xoay thân người ra trước hoặc sau thay vì giữ thẳng hàng."],"quickTip":"Nếu khó giữ thăng bằng, có thể chống thêm bàn chân dưới lên trên để tạo điểm tựa rộng hơn.","suggestedRestSeconds":45,"imageUrl":"https://images.pexels.com/photos/8436141/pexels-photo-8436141.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-chan-treo-xa-hanging-leg-raise","name":"Nâng chân treo xà (Hanging Leg Raise)","primaryMuscle":"bung","secondaryMuscles":[],"equipment":["xa_ngang"],"difficulty":"advanced","instructions":["Treo người trên xà, hai tay nắm rộng bằng vai.","Siết bụng, nâng hai chân thẳng lên đến ngang hông hoặc cao hơn.","Giữ 1 giây ở điểm cao nhất, tránh đung đưa thân người.","Hạ chân xuống từ từ về vị trí ban đầu."],"commonMistakes":["Dùng đà đung đưa thân người để nâng chân lên.","Gập gối quá nhiều làm giảm hiệu quả lên cơ bụng dưới."],"quickTip":"Nếu chưa đủ sức nâng chân thẳng, bắt đầu với nâng gối (knee raise) trước.","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/7592439/pexels-photo-7592439.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-goi-treo-xa-hanging-knee-raise","name":"Nâng gối treo xà (Hanging Knee Raise)","primaryMuscle":"bung","secondaryMuscles":[],"equipment":["xa_ngang"],"difficulty":"intermediate","instructions":["Treo người trên xà, hai tay nắm rộng bằng vai.","Siết bụng, gập gối và nâng đầu gối lên sát ngực.","Giữ 1 giây ở điểm cao nhất.","Hạ chân xuống từ từ về vị trí ban đầu, tránh đung đưa."],"commonMistakes":["Đung đưa thân người để lấy đà nâng gối.","Chỉ nâng gối lên rất thấp, không đủ biên độ."],"quickTip":"Bài tập phù hợp làm bước đệm trước khi tập nâng chân thẳng khó hơn.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/6009289/pexels-photo-6009289.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"gap-bung-bang-cap-cable-crunch","name":"Gập bụng bằng cáp (Cable Crunch)","primaryMuscle":"bung","secondaryMuscles":[],"equipment":["may_keo_xo"],"difficulty":"intermediate","instructions":["Quỳ xuống đối diện máy cáp cao, nắm dây thừng hai bên đầu, đặt sát hai bên đầu.","Siết bụng, gập người xuống cong lưng trên, khuỷu tay hướng về phía gối.","Giữ 1 giây ở điểm gập thấp nhất.","Trở về tư thế thẳng người ban đầu có kiểm soát."],"commonMistakes":["Dùng lực tay kéo dây xuống thay vì gập bằng cơ bụng.","Gập hông thay vì gập cột sống trên."],"quickTip":"Chuyển động chính đến từ việc cong cột sống, không phải cúi hông về trước.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/3930989/pexels-photo-3930989.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-chan-nam-lying-leg-raise","name":"Nâng chân nằm (Lying Leg Raise)","primaryMuscle":"bung","secondaryMuscles":[],"equipment":["khong_dung_cu"],"difficulty":"beginner","instructions":["Nằm ngửa trên sàn, hai tay đặt dưới mông hoặc để dọc thân người, chân duỗi thẳng.","Siết bụng, nâng hai chân thẳng lên đến khoảng 90 độ.","Hạ chân xuống từ từ, không chạm sàn hoàn toàn giữa các lần lặp.","Giữ lưng dưới áp sát sàn trong suốt bài tập."],"commonMistakes":["Để lưng dưới cong lên khỏi sàn khi hạ chân.","Hạ chân quá nhanh mất kiểm soát."],"quickTip":"Nếu lưng dưới khó chịu, gập nhẹ đầu gối để giảm tải trong khi vẫn tập đúng nhóm cơ.","suggestedRestSeconds":45,"imageUrl":"https://images.pexels.com/photos/6516222/pexels-photo-6516222.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"plank-leo-nui-mountain-climber","name":"Plank leo núi (Mountain Climber)","primaryMuscle":"bung","secondaryMuscles":["dui_truoc"],"equipment":["khong_dung_cu"],"difficulty":"intermediate","instructions":["Vào tư thế plank cao, hai tay chống thẳng dưới vai.","Kéo nhanh một gối về phía ngực, sau đó trả về vị trí ban đầu.","Đổi chân liên tục theo nhịp nhanh, giữ hông ổn định.","Siết bụng suốt bài tập, không để hông nhô cao."],"commonMistakes":["Nhô hông lên cao làm mất tư thế plank chuẩn.","Chuyển động quá nhanh làm mất kiểm soát tư thế."],"quickTip":"Có thể điều chỉnh tốc độ chậm hơn để tập trung siết cơ bụng thay vì chỉ luyện tim mạch.","suggestedRestSeconds":45,"imageUrl":"https://images.pexels.com/photos/6516165/pexels-photo-6516165.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"gap-bung-co-ta","name":"Gập bụng có tạ","primaryMuscle":"bung","secondaryMuscles":[],"equipment":["ta_don"],"difficulty":"intermediate","instructions":["Nằm ngửa, gối gập, hai bàn chân đặt sát sàn, ôm tạ đơn trước ngực.","Siết bụng, nâng thân người lên đến khi lưng gần vuông góc sàn.","Giữ 1 giây ở điểm cao nhất.","Hạ người xuống từ từ về vị trí ban đầu."],"commonMistakes":["Dùng đà giật người lên thay vì kiểm soát bằng cơ bụng.","Ôm tạ quá xa ngực làm mất thăng bằng."],"quickTip":"Chỉ thêm tạ khi đã thực hiện tốt gập bụng thường với kỹ thuật chuẩn.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/3931367/pexels-photo-3931367.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"xoay-nguoi-nga-russian-twist","name":"Xoay người Nga (Russian Twist)","primaryMuscle":"bung","secondaryMuscles":[],"equipment":["ta_don"],"difficulty":"intermediate","instructions":["Ngồi trên sàn, gối gập, nâng hai chân khỏi sàn hoặc giữ chạm nhẹ để dễ hơn.","Ngả thân người ra sau khoảng 45 độ, hai tay cầm tạ đơn trước bụng.","Xoay thân người sang một bên, chạm tạ gần sàn, rồi xoay sang bên kia.","Giữ lưng thẳng, siết bụng suốt quá trình xoay."],"commonMistakes":["Gù lưng thay vì giữ thân người thẳng khi ngả ra sau.","Xoay chỉ bằng cánh tay, không xoay từ vùng bụng."],"quickTip":"Chạm chân xuống sàn nếu mới tập để giảm độ khó, nâng chân lên khi đã quen.","suggestedRestSeconds":45,"imageUrl":"https://images.pexels.com/photos/5128466/pexels-photo-5128466.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"dead-bug","name":"Dead Bug","primaryMuscle":"bung","secondaryMuscles":["lung_duoi"],"equipment":["khong_dung_cu"],"difficulty":"beginner","instructions":["Nằm ngửa, hai tay duỗi thẳng lên trần, gối gập 90 độ nâng khỏi sàn.","Siết bụng, ép lưng dưới sát sàn.","Duỗi thẳng đồng thời tay phải và chân trái xuống gần sàn, giữ lưng không nhấc lên.","Trở về vị trí ban đầu, đổi bên với tay trái và chân phải."],"commonMistakes":["Để lưng dưới nhấc khỏi sàn khi duỗi tay chân.","Duỗi tay chân quá nhanh, mất kiểm soát."],"quickTip":"Bài tập tốt để luyện khả năng giữ ổn định cột sống, phù hợp cả người mới và phục hồi chấn thương nhẹ.","suggestedRestSeconds":45,"imageUrl":"https://images.pexels.com/photos/38760563/pexels-photo-38760563.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"plank-cham-vai-shoulder-tap-plank","name":"Plank chạm vai (Shoulder Tap Plank)","primaryMuscle":"bung","secondaryMuscles":["vai_truoc"],"equipment":["khong_dung_cu"],"difficulty":"intermediate","instructions":["Vào tư thế plank cao, hai tay chống thẳng dưới vai, chân mở rộng bằng vai để tăng độ vững.","Nâng một tay lên chạm vào vai đối diện.","Đặt tay trở lại sàn, đổi tay chạm vai còn lại.","Giữ hông ổn định, không xoay lắc trong suốt bài tập."],"commonMistakes":["Để hông xoay lắc theo tay đang chạm vai.","Chân đặt quá hẹp làm giảm độ vững của thân người."],"quickTip":"Càng giữ hông bất động càng chứng tỏ cơ bụng đang làm việc hiệu quả.","suggestedRestSeconds":45,"imageUrl":"https://images.pexels.com/photos/4998815/pexels-photo-4998815.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"gap-bung-chu-v-v-up","name":"Gập bụng chữ V (V-up)","primaryMuscle":"bung","secondaryMuscles":[],"equipment":["khong_dung_cu"],"difficulty":"advanced","instructions":["Nằm ngửa trên sàn, hai tay duỗi thẳng qua đầu, hai chân duỗi thẳng.","Đồng thời nâng thân trên và hai chân lên, cố gắng chạm tay vào mũi chân tạo hình chữ V.","Giữ 1 giây ở điểm cao nhất, siết chặt cơ bụng.","Hạ người xuống từ từ về vị trí ban đầu."],"commonMistakes":["Gập gối để dễ chạm chân hơn thay vì giữ chân thẳng.","Dùng đà hất người lên thay vì kiểm soát bằng cơ bụng."],"quickTip":"Nếu chưa đủ sức, có thể gập gối nhẹ hoặc chỉ nâng thân trên trước khi tập biến thể đầy đủ.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/8402224/pexels-photo-8402224.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"gap-bung-dung-bang-day-khang-luc","name":"Gập bụng đứng bằng dây kháng lực","primaryMuscle":"bung","secondaryMuscles":[],"equipment":["day_khang_luc"],"difficulty":"beginner","instructions":["Cố định dây kháng lực phía trên cao, đứng quay lưng lại điểm cố định, hai tay nắm dây ngang đầu.","Giữ hông cố định, gập người về phía trước bằng cách cong cột sống trên.","Giữ 1 giây ở điểm gập thấp nhất, siết chặt bụng.","Trở về tư thế đứng thẳng ban đầu có kiểm soát."],"commonMistakes":["Gập hông thay vì gập cột sống trên.","Dùng lực tay kéo dây xuống thay vì gập bằng cơ bụng."],"quickTip":"Đây là biến thể đứng của gập bụng cáp, phù hợp khi không có máy cáp cố định.","suggestedRestSeconds":45,"imageUrl":"https://images.pexels.com/photos/8846567/pexels-photo-8846567.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"romanian-deadlift-ta-don","name":"Romanian Deadlift tạ đòn","primaryMuscle":"dui_sau","secondaryMuscles":["mong","lung_duoi"],"equipment":["ta_doi"],"difficulty":"intermediate","instructions":["Đứng thẳng, nắm tạ đòn rộng bằng vai, tạ sát đùi trước.","Đẩy hông ra sau, hạ tạ xuống dọc theo chân, giữ lưng thẳng và gối hơi khuỵu.","Hạ đến khi cảm nhận căng rõ ở đùi sau, thường ngang ống chân.","Đẩy hông về trước để đứng thẳng dậy trở lại."],"commonMistakes":["Gập lưng thay vì gập hông khi hạ tạ xuống.","Gập gối quá nhiều biến thành động tác squat."],"quickTip":"Giữ tạ sát chân suốt bài để bảo vệ lưng dưới và tối ưu lực vào đùi sau.","suggestedRestSeconds":120,"imageUrl":"https://images.pexels.com/photos/4853280/pexels-photo-4853280.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"romanian-deadlift-ta-don-2","name":"Romanian Deadlift tạ đơn","primaryMuscle":"dui_sau","secondaryMuscles":["mong","lung_duoi"],"equipment":["ta_don"],"difficulty":"beginner","instructions":["Đứng thẳng, mỗi tay cầm tạ đơn trước đùi.","Đẩy hông ra sau, hạ tạ xuống dọc theo chân, giữ lưng thẳng.","Hạ đến khi cảm nhận căng ở đùi sau.","Đẩy hông về trước để đứng thẳng dậy trở lại."],"commonMistakes":["Cong lưng trên khi cúi người xuống thấp.","Đẩy tạ ra xa thân người thay vì giữ sát chân."],"quickTip":"Phù hợp làm bài học kỹ thuật gập hông trước khi tập RDL tạ đòn nặng hơn.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/1552103/pexels-photo-1552103.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"gap-goi-tren-may-nam","name":"Gập gối trên máy nằm","primaryMuscle":"dui_sau","secondaryMuscles":[],"equipment":["may_tap_chan"],"difficulty":"beginner","instructions":["Nằm sấp lên máy, đệm chặn đặt ngay trên gót chân.","Nắm tay cầm hai bên, giữ hông áp sát ghế.","Gập gối kéo đệm chặn lên sát mông.","Hạ chân xuống từ từ về vị trí ban đầu."],"commonMistakes":["Nhấc hông khỏi ghế khi gập gối lên cao.","Dùng đà hất chân thay vì gập có kiểm soát."],"quickTip":"Giữ 1 giây ở điểm gập cao nhất để tăng hiệu quả kích hoạt cơ đùi sau.","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/28731788/pexels-photo-28731788.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"gap-goi-tren-may-ngoi","name":"Gập gối trên máy ngồi","primaryMuscle":"dui_sau","secondaryMuscles":[],"equipment":["may_tap_chan"],"difficulty":"beginner","instructions":["Ngồi vào máy, đệm chặn đặt ngay trên mắt cá chân, đùi cố định dưới đệm trên.","Nắm tay cầm hai bên để giữ ổn định thân người.","Gập gối kéo đệm chặn xuống dưới ghế.","Trả chân lên từ từ về vị trí ban đầu."],"commonMistakes":["Dùng đà thân trên để kéo đệm xuống.","Không hạ hết biên độ về vị trí ban đầu giữa các lần lặp."],"quickTip":"Máy ngồi giúp cô lập tốt đùi sau vì hông đã được cố định sẵn.","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/34433962/pexels-photo-34433962.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"deadlift-chan-thang-ta-don","name":"Deadlift chân thẳng tạ đơn","primaryMuscle":"dui_sau","secondaryMuscles":["mong","lung_duoi"],"equipment":["ta_don"],"difficulty":"intermediate","instructions":["Đứng thẳng, mỗi tay cầm tạ đơn trước đùi, chân giữ gần thẳng (chỉ hơi khuỵu nhẹ).","Gập hông hạ tạ xuống dọc theo chân, giữ lưng thẳng.","Hạ đến khi cảm nhận căng rõ rệt ở đùi sau, không cần chạm sàn.","Đẩy hông về trước để đứng thẳng dậy trở lại."],"commonMistakes":["Khóa cứng hoàn toàn khớp gối gây áp lực lên khớp.","Cong lưng để cố hạ tạ thấp hơn khả năng linh hoạt cho phép."],"quickTip":"Biên độ chuyển động phụ thuộc vào độ linh hoạt của từng người, không cần cố chạm sàn.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/4793199/pexels-photo-4793199.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"deadlift-chan-thang-ta-don-2","name":"Deadlift chân thẳng tạ đòn","primaryMuscle":"dui_sau","secondaryMuscles":["mong","lung_duoi"],"equipment":["ta_doi"],"difficulty":"advanced","instructions":["Đứng thẳng, nắm tạ đòn rộng bằng vai, chân giữ gần thẳng.","Gập hông hạ tạ xuống dọc theo chân, giữ lưng thẳng suốt bài tập.","Hạ đến khi cảm nhận căng rõ ở đùi sau.","Đẩy hông về trước để đứng thẳng dậy trở lại."],"commonMistakes":["Dùng tạ quá nặng khi độ linh hoạt đùi sau còn hạn chế.","Cong lưng dưới để cố hạ tạ thấp hơn."],"quickTip":"Đây là biến thể nâng cao của Romanian Deadlift, chỉ nên tập khi đã vững kỹ thuật RDL.","suggestedRestSeconds":120,"imageUrl":"https://images.pexels.com/photos/5327527/pexels-photo-5327527.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nordic-hamstring-curl","name":"Nordic Hamstring Curl","primaryMuscle":"dui_sau","secondaryMuscles":["mong"],"equipment":["khong_dung_cu"],"difficulty":"advanced","instructions":["Quỳ gối trên thảm, có người hoặc vật cố định giữ chặt cổ chân.","Giữ thân người thẳng từ đầu gối đến đầu, từ từ hạ người về phía trước.","Dùng cơ đùi sau kiểm soát tốc độ hạ xuống càng lâu càng tốt.","Khi không kiểm soát được nữa, dùng tay chống đỡ nhẹ xuống sàn rồi đẩy người trở lại."],"commonMistakes":["Gập hông trong lúc hạ người thay vì giữ thân thẳng.","Hạ người quá nhanh không kiểm soát ở giai đoạn đầu."],"quickTip":"Bài tập rất khó, nên bắt đầu với biên độ nhỏ và tăng dần theo thời gian.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/4804303/pexels-photo-4804303.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"romanian-deadlift-mot-chan-ta-don","name":"Romanian Deadlift một chân tạ đơn","primaryMuscle":"dui_sau","secondaryMuscles":["mong"],"equipment":["ta_don"],"difficulty":"advanced","instructions":["Đứng thẳng trên một chân, tay cùng bên hoặc đối diện cầm tạ đơn.","Gập hông, đưa chân kia duỗi thẳng ra sau, hạ tạ xuống dọc theo chân trụ.","Giữ lưng thẳng và hông vuông góc với sàn trong suốt chuyển động.","Đẩy hông về trước để đứng thẳng dậy, hoàn thành hiệp rồi đổi chân."],"commonMistakes":["Xoay hông sang một bên thay vì giữ vuông góc với sàn.","Mất thăng bằng do dùng tạ quá nặng khi mới tập."],"quickTip":"Tập không tạ trước để làm chủ thăng bằng, sau đó mới thêm tạ.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/949129/pexels-photo-949129.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"keo-ta-day-thung-giua-hai-chan-cable-pull-through","name":"Kéo tạ dây thừng giữa hai chân (Cable Pull-through)","primaryMuscle":"dui_sau","secondaryMuscles":["mong","lung_duoi"],"equipment":["may_keo_xo"],"difficulty":"intermediate","instructions":["Đứng quay lưng về phía máy cáp thấp, dây thừng luồn giữa hai chân.","Đứng chân rộng bằng vai, cúi người về trước bằng cách gập hông, tay giữ dây thừng thả xuống.","Đẩy hông về trước đứng thẳng dậy, kéo dây thừng lên qua giữa hai chân.","Trở lại tư thế cúi người, lặp lại đều nhịp."],"commonMistakes":["Gập lưng thay vì gập hông khi cúi người.","Đứng quá gần máy khiến biên độ chuyển động bị rút ngắn."],"quickTip":"Bài tập giúp luyện đúng mẫu chuyển động gập hông (hip hinge) rất an toàn cho lưng.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/5327503/pexels-photo-5327503.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"gap-goi-bang-day-khang-luc","name":"Gập gối bằng dây kháng lực","primaryMuscle":"dui_sau","secondaryMuscles":[],"equipment":["day_khang_luc"],"difficulty":"beginner","instructions":["Cố định dây kháng lực quanh mắt cá chân và một điểm cố định phía sau.","Đứng thẳng, tay có thể vịn nhẹ vào tường hoặc ghế để giữ thăng bằng.","Gập gối kéo gót chân về phía mông.","Trả chân về vị trí ban đầu từ từ, đổi bên sau khi hết hiệp."],"commonMistakes":["Đứng lắc lư mất thăng bằng trong lúc gập gối.","Gập gối không hết biên độ do dây quá căng."],"quickTip":"Phù hợp tập bổ trợ đùi sau tại nhà khi không có máy gập gối.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/4970967/pexels-photo-4970967.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"deadlift-mot-chan-khong-ta","name":"Deadlift một chân không tạ","primaryMuscle":"dui_sau","secondaryMuscles":["mong"],"equipment":["khong_dung_cu"],"difficulty":"beginner","instructions":["Đứng thẳng trên một chân, hai tay thả tự nhiên hoặc chống hông.","Gập hông, đưa chân kia duỗi thẳng ra sau, thân trên hạ xuống song song sàn.","Giữ lưng thẳng, hông vuông góc với sàn.","Đẩy hông về trước để đứng thẳng dậy, đổi chân sau khi hết hiệp."],"commonMistakes":["Xoay hông hoặc vai để giữ thăng bằng thay vì siết core.","Cong lưng khi hạ thân người xuống thấp."],"quickTip":"Bài tập tốt để luyện thăng bằng và kích hoạt đùi sau trước khi tập các biến thể có tạ.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/841125/pexels-photo-841125.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"squat-ta-don-sau-gay","name":"Squat tạ đòn sau gáy","primaryMuscle":"dui_truoc","secondaryMuscles":["mong"],"equipment":["ta_doi"],"difficulty":"advanced","instructions":["Đặt thanh đòn lên phần trên lưng trên (trapezius), đứng chân rộng bằng vai.","Siết bụng, hạ người xuống bằng cách gập gối và đẩy hông ra sau, giữ lưng thẳng.","Hạ đến khi đùi song song sàn hoặc thấp hơn nếu độ linh hoạt cho phép.","Đứng thẳng dậy trở lại bằng lực đẩy từ chân."],"commonMistakes":["Đầu gối đổ vào trong khi đứng lên.","Cong lưng dưới ở điểm thấp nhất của squat."],"quickTip":"Luôn có giá đỡ an toàn (rack) hoặc người hỗ trợ khi tập squat nặng.","suggestedRestSeconds":150,"imageUrl":"https://images.pexels.com/photos/38576481/pexels-photo-38576481.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"squat-ta-don-truoc","name":"Squat tạ đòn trước","primaryMuscle":"dui_truoc","secondaryMuscles":["bung"],"equipment":["ta_doi"],"difficulty":"advanced","instructions":["Đặt thanh đòn lên phía trước vai, khuỷu tay nâng cao để giữ tạ ổn định.","Đứng chân rộng bằng vai, siết bụng.","Hạ người xuống giữ thân trên thẳng đứng hơn so với squat sau gáy.","Đứng thẳng dậy trở lại bằng lực đẩy từ chân."],"commonMistakes":["Hạ khuỷu tay xuống khiến tạ dễ tuột khỏi vai.","Đổ người về trước quá nhiều khi xuống thấp."],"quickTip":"Squat trước đòi hỏi cổ tay và vai linh hoạt hơn, có thể tập làm quen tư thế trước khi thêm tạ.","suggestedRestSeconds":150,"imageUrl":"https://images.pexels.com/photos/3926639/pexels-photo-3926639.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"squat-ta-don-goblet-squat","name":"Squat tạ đơn (Goblet Squat)","primaryMuscle":"dui_truoc","secondaryMuscles":["mong","bung"],"equipment":["ta_don"],"difficulty":"beginner","instructions":["Đứng chân rộng hơn vai một chút, hai tay cầm một tạ đơn sát ngực.","Siết bụng, hạ người xuống giữa hai chân, giữ lưng thẳng.","Hạ đến khi khuỷu tay chạm nhẹ vào đùi trong.","Đứng thẳng dậy trở lại bằng lực đẩy từ chân."],"commonMistakes":["Cúi người về trước thay vì hạ thẳng xuống.","Nhấc gót chân khỏi sàn khi xuống thấp."],"quickTip":"Bài tập vào squat lý tưởng cho người mới vì tạ ở phía trước giúp giữ thăng bằng tự nhiên.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/4587364/pexels-photo-4587364.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"day-dui-tren-may-leg-press","name":"Đẩy đùi trên máy (Leg Press)","primaryMuscle":"dui_truoc","secondaryMuscles":["mong"],"equipment":["may_tap_chan"],"difficulty":"beginner","instructions":["Ngồi vào máy, đặt hai chân rộng bằng vai lên bệ đẩy.","Đẩy bệ ra xa cho đến khi chân gần thẳng, không khóa cứng khớp gối.","Hạ bệ về gần cơ thể đến khi gối gập khoảng 90 độ.","Đẩy bệ ra trở lại, kiểm soát tốc độ suốt bài tập."],"commonMistakes":["Hạ bệ quá sâu khiến hông nhấc khỏi ghế tựa.","Khóa cứng khớp gối ở điểm đẩy xa nhất."],"quickTip":"Đặt chân cao trên bệ để nhắm nhiều hơn vào mông, đặt thấp để nhắm nhiều hơn vào đùi trước.","suggestedRestSeconds":120,"imageUrl":"https://images.pexels.com/photos/3076512/pexels-photo-3076512.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"duoi-chan-tren-may-leg-extension","name":"Duỗi chân trên máy (Leg Extension)","primaryMuscle":"dui_truoc","secondaryMuscles":[],"equipment":["may_tap_chan"],"difficulty":"beginner","instructions":["Ngồi vào máy, chỉnh đệm chặn sao cho nằm ngay trên mắt cá chân.","Lưng tựa chắc vào ghế, hai tay nắm tay cầm hai bên.","Duỗi thẳng chân lên đến khi gần thẳng hoàn toàn.","Hạ chân xuống từ từ về vị trí ban đầu."],"commonMistakes":["Duỗi và hạ chân quá nhanh, dùng đà thay vì kiểm soát.","Chỉnh đệm chặn sai vị trí gây khó chịu ở mắt cá chân."],"quickTip":"Giữ 1 giây ở điểm duỗi thẳng để tăng hiệu quả kích hoạt cơ đùi trước.","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/6539840/pexels-photo-6539840.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"day-dui-kieu-hack-squat","name":"Đẩy đùi kiểu Hack Squat","primaryMuscle":"dui_truoc","secondaryMuscles":["mong"],"equipment":["may_tap_chan"],"difficulty":"intermediate","instructions":["Đứng vào máy Hack Squat, lưng và vai tựa chắc vào đệm, chân đặt rộng bằng vai trên bệ.","Mở khóa an toàn, hạ người xuống bằng cách gập gối.","Hạ đến khi đùi song song bệ hoặc thấp hơn nếu thoải mái.","Đẩy người lên trở lại vị trí ban đầu."],"commonMistakes":["Đặt chân quá cao hoặc quá thấp trên bệ gây lệch trọng tâm.","Không khóa an toàn trước khi bắt đầu, gây nguy hiểm."],"quickTip":"Máy Hack Squat cố định quỹ đạo chuyển động, an toàn hơn squat tự do khi tập một mình.","suggestedRestSeconds":120,"imageUrl":"https://images.pexels.com/photos/19025671/pexels-photo-19025671.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"buoc-tan-ta-don","name":"Bước tấn tạ đơn","primaryMuscle":"dui_truoc","secondaryMuscles":["mong"],"equipment":["ta_don"],"difficulty":"intermediate","instructions":["Đứng thẳng, mỗi tay cầm tạ đơn thả tự nhiên hai bên.","Bước một chân dài về phía trước, hạ người xuống đến khi cả hai gối gập khoảng 90 độ.","Đẩy người trở lại vị trí đứng ban đầu bằng lực chân trước.","Đổi chân, thực hiện đều hai bên."],"commonMistakes":["Gối chân trước vượt quá mũi chân quá nhiều.","Bước quá ngắn khiến trọng tâm mất cân bằng."],"quickTip":"Giữ thân người thẳng đứng, không đổ người về trước khi bước.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/6339676/pexels-photo-6339676.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"buoc-tan-ta-don-2","name":"Bước tấn tạ đòn","primaryMuscle":"dui_truoc","secondaryMuscles":["mong"],"equipment":["ta_doi"],"difficulty":"advanced","instructions":["Đặt thanh đòn lên lưng trên như tư thế squat, đứng thẳng.","Bước một chân dài về phía trước, hạ người xuống đến khi gối gập khoảng 90 độ.","Đẩy người trở lại vị trí đứng ban đầu.","Đổi chân, thực hiện đều hai bên."],"commonMistakes":["Mất thăng bằng do tạ đòn cố định trên vai khó điều chỉnh giữa chừng.","Bước quá ngắn hoặc quá dài so với chiều cao cơ thể."],"quickTip":"Làm quen bước tấn với tạ đơn trước khi chuyển sang tạ đòn để quen giữ thăng bằng.","suggestedRestSeconds":120,"imageUrl":"https://images.pexels.com/photos/30994841/pexels-photo-30994841.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"buoc-tan-di-bo-ta-don","name":"Bước tấn đi bộ tạ đơn","primaryMuscle":"dui_truoc","secondaryMuscles":["mong"],"equipment":["ta_don"],"difficulty":"intermediate","instructions":["Đứng thẳng, mỗi tay cầm tạ đơn, chuẩn bị không gian di chuyển về phía trước.","Bước một chân dài về phía trước, hạ người xuống đến khi gối gập 90 độ.","Đẩy người lên và bước tiếp chân sau lên phía trước để tiếp tục bước tấn.","Di chuyển liên tục về phía trước, luân phiên hai chân."],"commonMistakes":["Bước không đủ dài khiến gối trước bị dồn áp lực.","Mất thăng bằng khi chuyển trọng tâm giữa các bước."],"quickTip":"Cần không gian di chuyển đủ dài, phù hợp tập ngoài trời hoặc phòng tập rộng.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/6339695/pexels-photo-6339695.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"squat-bulgarian-mot-chan","name":"Squat Bulgarian một chân","primaryMuscle":"dui_truoc","secondaryMuscles":["mong"],"equipment":["ta_don","ghe_tap"],"difficulty":"advanced","instructions":["Đứng quay lưng về phía ghế, đặt mu bàn chân sau lên mặt ghế.","Mỗi tay cầm tạ đơn, hạ người xuống bằng chân trước đến khi gối gập khoảng 90 độ.","Đẩy người lên trở lại vị trí ban đầu bằng lực chân trước.","Hoàn thành hiệp rồi đổi chân."],"commonMistakes":["Đặt chân sau quá gần hoặc quá xa ghế làm mất thăng bằng.","Đổ người về trước quá nhiều thay vì giữ thân thẳng."],"quickTip":"Bài tập một chân giúp phát hiện rõ sự mất cân bằng sức mạnh giữa hai bên chân.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/4662333/pexels-photo-4662333.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"squat-khong-ta","name":"Squat không tạ","primaryMuscle":"dui_truoc","secondaryMuscles":["mong"],"equipment":["khong_dung_cu"],"difficulty":"beginner","instructions":["Đứng chân rộng bằng vai, hai tay duỗi thẳng trước mặt để giữ thăng bằng.","Hạ người xuống bằng cách gập gối và đẩy hông ra sau, giữ lưng thẳng.","Hạ đến khi đùi song song sàn hoặc thấp hơn nếu thoải mái.","Đứng thẳng dậy trở lại vị trí ban đầu."],"commonMistakes":["Nhấc gót chân khỏi sàn khi hạ người xuống.","Đầu gối đổ vào trong khi đứng lên."],"quickTip":"Bài tập nền tảng nên tập thành thạo trước khi thêm tạ vào squat.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/8401827/pexels-photo-8401827.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"squat-nhay","name":"Squat nhảy","primaryMuscle":"dui_truoc","secondaryMuscles":["mong","bap_chan"],"equipment":["khong_dung_cu"],"difficulty":"intermediate","instructions":["Đứng chân rộng bằng vai, hạ người xuống tư thế squat.","Bật nhảy thẳng lên cao hết sức, duỗi thẳng thân người trên không.","Tiếp đất nhẹ nhàng bằng cả bàn chân, gập gối để giảm chấn động.","Hạ ngay xuống tư thế squat để chuẩn bị lần nhảy tiếp theo."],"commonMistakes":["Tiếp đất bằng mũi chân cứng, không gập gối giảm chấn.","Nhảy liên tục quá nhanh mà không kiểm soát tư thế mỗi lần."],"quickTip":"Bài tập cường độ cao, nên khởi động kỹ khớp gối và mắt cá trước khi tập.","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/2468366/pexels-photo-2468366.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"buoc-len-buc-ta-don","name":"Bước lên bục tạ đơn","primaryMuscle":"dui_truoc","secondaryMuscles":["mong"],"equipment":["ta_don","ghe_tap"],"difficulty":"intermediate","instructions":["Đứng đối diện ghế hoặc bục chắc chắn, mỗi tay cầm tạ đơn.","Bước một chân lên bục, đẩy người lên bằng lực chân đó cho đến khi đứng thẳng trên bục.","Bước chân còn lại lên theo, sau đó bước xuống lần lượt từng chân.","Đổi chân dẫn đầu sau mỗi hiệp."],"commonMistakes":["Đẩy người lên bằng lực chân dưới (đạp đất) thay vì chân trên bục.","Chọn bục quá cao khiến mất thăng bằng."],"quickTip":"Chọn độ cao bục sao cho gối gập khoảng 90 độ khi đặt chân lên.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/8401821/pexels-photo-8401821.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"squat-tuong-wall-sit","name":"Squat tường (Wall Sit)","primaryMuscle":"dui_truoc","secondaryMuscles":[],"equipment":["khong_dung_cu"],"difficulty":"beginner","instructions":["Đứng tựa lưng vào tường, hai chân bước ra trước khoảng một bước chân.","Trượt lưng xuống theo tường đến khi gối gập khoảng 90 độ.","Giữ tư thế này, đùi song song sàn, lưng áp sát tường.","Giữ theo thời gian quy định rồi trượt lưng lên đứng thẳng."],"commonMistakes":["Gối vượt quá mũi chân gây áp lực lên khớp gối.","Không giữ lưng áp sát tường trong suốt thời gian giữ."],"quickTip":"Bài tập tĩnh tốt để tăng sức bền cơ đùi trước, không cần thiết bị.","suggestedRestSeconds":45,"imageUrl":"https://images.pexels.com/photos/8401958/pexels-photo-8401958.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"squat-bang-day-khang-luc","name":"Squat bằng dây kháng lực","primaryMuscle":"dui_truoc","secondaryMuscles":["mong"],"equipment":["day_khang_luc"],"difficulty":"beginner","instructions":["Đứng lên giữa dây kháng lực, kéo hai đầu dây lên đặt ngang vai.","Đứng chân rộng bằng vai, siết bụng.","Hạ người xuống tư thế squat, giữ lưng thẳng.","Đứng thẳng dậy trở lại, dây luôn căng trong suốt bài tập."],"commonMistakes":["Đứng lên dây quá lỏng làm giảm lực cản.","Cúi người về trước thay vì hạ thẳng xuống."],"quickTip":"Phù hợp tập squat có kháng lực khi không có tạ, ví dụ khi tập tại nhà hoặc đi công tác.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/6339655/pexels-photo-6339655.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"superman","name":"Superman","primaryMuscle":"lung_duoi","secondaryMuscles":["mong"],"equipment":["khong_dung_cu"],"difficulty":"beginner","instructions":["Nằm sấp trên sàn hoặc thảm tập, hai tay duỗi thẳng qua đầu.","Đồng thời nâng tay, ngực và chân lên khỏi sàn.","Giữ tư thế 1-2 giây ở điểm cao nhất, siết chặt lưng dưới và mông.","Hạ người xuống từ từ về vị trí ban đầu."],"commonMistakes":["Nâng người quá cao gây ưỡn cột sống quá mức.","Nín thở thay vì thở đều trong lúc giữ tư thế."],"quickTip":"Chuyển động nên chậm và kiểm soát, không dùng đà hất người lên.","suggestedRestSeconds":45,"imageUrl":"https://images.pexels.com/photos/4976936/pexels-photo-4976936.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-ta-don-kieu-deadlift","name":"Nâng tạ đòn kiểu Deadlift","primaryMuscle":"lung_duoi","secondaryMuscles":["mong","dui_sau"],"equipment":["ta_doi"],"difficulty":"advanced","instructions":["Đứng chân rộng bằng hông, thanh tạ sát ống chân, cúi người nắm tạ rộng bằng vai.","Giữ lưng thẳng, ngực ưỡn, mắt nhìn về phía trước.","Đứng thẳng dậy bằng lực đẩy từ chân và hông, kéo tạ sát người.","Hạ tạ xuống có kiểm soát theo đúng quỹ đạo lúc nâng lên."],"commonMistakes":["Cong lưng khi nâng tạ, đặc biệt lúc tạ rời sàn.","Để tạ ra xa cơ thể làm tăng áp lực lên lưng dưới."],"quickTip":"Học đúng kỹ thuật với tạ nhẹ trước khi tăng mức tạ, đây là bài dễ chấn thương nếu sai form.","suggestedRestSeconds":150,"imageUrl":"https://images.pexels.com/photos/19132573/pexels-photo-19132573.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-ta-don-kieu-deadlift-2","name":"Nâng tạ đơn kiểu Deadlift","primaryMuscle":"lung_duoi","secondaryMuscles":["mong","dui_sau"],"equipment":["ta_don"],"difficulty":"intermediate","instructions":["Đứng chân rộng bằng hông, mỗi tay cầm một tạ đơn phía trước đùi.","Đẩy hông ra sau, cúi người xuống trong khi giữ lưng thẳng, tạ sát ống chân.","Đứng thẳng dậy bằng lực chân và hông.","Siết mông ở điểm cao nhất, không ngả người ra sau quá mức."],"commonMistakes":["Cúi người bằng cách gập lưng thay vì gập hông.","Đầu gối đẩy về trước quá nhiều biến thành động tác squat."],"quickTip":"Phù hợp làm bài khởi động kỹ thuật trước khi tập deadlift tạ đòn nặng.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/9171160/pexels-photo-9171160.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"good-morning-ta-don","name":"Good Morning tạ đòn","primaryMuscle":"lung_duoi","secondaryMuscles":["dui_sau","mong"],"equipment":["ta_doi"],"difficulty":"advanced","instructions":["Đặt thanh đòn nhẹ lên vai như tư thế squat, đứng chân rộng bằng hông.","Giữ lưng thẳng, gối hơi khuỵu, đẩy hông ra sau và cúi người về trước.","Cúi đến khi thân người gần song song sàn, cảm nhận căng ở đùi sau và lưng dưới.","Đứng thẳng dậy trở lại bằng lực hông."],"commonMistakes":["Dùng tạ quá nặng khi chưa vững kỹ thuật, rất dễ gây chấn thương lưng.","Cong lưng trên trong lúc cúi người."],"quickTip":"Bắt đầu với thanh đòn không tạ hoặc tạ rất nhẹ để làm quen chuyển động gập hông.","suggestedRestSeconds":120,"imageUrl":"https://images.pexels.com/photos/5327456/pexels-photo-5327456.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-lung-duoi-tren-ghe-hyperextension","name":"Nâng lưng dưới trên ghế (Hyperextension)","primaryMuscle":"lung_duoi","secondaryMuscles":["mong","dui_sau"],"equipment":["ghe_tap"],"difficulty":"intermediate","instructions":["Nằm sấp trên ghế, cố định phần hông và cổ chân, thân trên thả tự do phía trước.","Khoanh tay trước ngực hoặc đặt sau đầu.","Nâng thân trên lên đến khi thân người thẳng hàng với chân.","Hạ người xuống từ từ đến khi cảm nhận căng nhẹ ở lưng dưới."],"commonMistakes":["Nâng người quá cao, ưỡn lưng quá mức ở điểm cao nhất.","Dùng đà hất người thay vì kiểm soát bằng cơ lưng dưới."],"quickTip":"Có thể ôm thêm tạ đơn trước ngực khi động tác đã trở nên dễ dàng.","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/13460171/pexels-photo-13460171.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"bird-dog","name":"Bird Dog","primaryMuscle":"lung_duoi","secondaryMuscles":["bung","mong"],"equipment":["khong_dung_cu"],"difficulty":"beginner","instructions":["Quỳ bốn điểm chống trên sàn, tay thẳng dưới vai, gối thẳng dưới hông.","Duỗi thẳng đồng thời một tay và chân đối diện ra xa.","Giữ thân người ổn định, không để hông xoay hoặc lưng võng.","Trở về tư thế ban đầu và đổi bên."],"commonMistakes":["Xoay hông theo tay/chân đang duỗi thay vì giữ thẳng.","Duỗi tay chân quá nhanh, mất kiểm soát thăng bằng."],"quickTip":"Tập chậm và giữ 2-3 giây ở điểm duỗi xa nhất để tăng hiệu quả ổn định cột sống.","suggestedRestSeconds":45,"imageUrl":"https://images.pexels.com/photos/37835856/pexels-photo-37835856.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"plank-ngua-reverse-plank","name":"Plank ngửa (Reverse Plank)","primaryMuscle":"lung_duoi","secondaryMuscles":["mong","bung"],"equipment":["khong_dung_cu"],"difficulty":"intermediate","instructions":["Ngồi trên sàn, hai chân duỗi thẳng, hai tay chống sau lưng ngang vai.","Nâng hông lên cao cho đến khi thân người tạo đường thẳng từ vai đến gót chân.","Siết mông và lưng dưới, giữ đầu thẳng hàng với thân.","Giữ tư thế theo thời gian quy định rồi hạ hông xuống."],"commonMistakes":["Để hông chùng xuống thấp hơn vai và gót chân.","Ngửa cổ ra sau quá mức thay vì giữ thẳng hàng."],"quickTip":"Nếu cổ tay khó chịu, có thể chống trên nắm tay thay vì lòng bàn tay.","suggestedRestSeconds":45,"imageUrl":"https://images.pexels.com/photos/5038855/pexels-photo-5038855.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"cheo-ta-don-kieu-pendlay","name":"Chèo tạ đòn kiểu Pendlay","primaryMuscle":"lung_duoi","secondaryMuscles":["lung_tren","tay_truoc"],"equipment":["ta_doi"],"difficulty":"advanced","instructions":["Cúi người song song sàn, nắm tạ đòn đặt trên sàn rộng bằng vai.","Giữ lưng thẳng cố định trong suốt bài tập, không đứng lên giữa các lần lặp.","Kéo tạ từ sàn lên chạm bụng dưới bằng lực lưng.","Hạ tạ chạm sàn hoàn toàn trước khi thực hiện lần lặp tiếp theo."],"commonMistakes":["Đứng thẳng người lên giữa các lần lặp thay vì giữ nguyên góc cúi.","Giật tạ bằng lực lưng dưới thay vì kéo có kiểm soát."],"quickTip":"Bài này đòi hỏi sức bền lưng dưới lớn, nên tập với tạ nhẹ hơn chèo tạ đòn thông thường.","suggestedRestSeconds":120,"imageUrl":"https://images.pexels.com/photos/6551083/pexels-photo-6551083.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-ta-don-kieu-sumo-deadlift","name":"Nâng tạ đòn kiểu Sumo Deadlift","primaryMuscle":"lung_duoi","secondaryMuscles":["mong","dui_truoc"],"equipment":["ta_doi"],"difficulty":"advanced","instructions":["Đứng chân rộng hơn vai, mũi chân hướng chéo ra ngoài, thanh tạ sát ống chân.","Cúi người nắm tạ bằng hai tay ở giữa hai chân, giữ lưng thẳng.","Đứng thẳng dậy bằng lực đẩy chân và hông, kéo tạ sát người.","Hạ tạ xuống có kiểm soát về vị trí ban đầu."],"commonMistakes":["Đứng chân chưa đủ rộng khiến bài tập giống deadlift thường.","Đầu gối đổ vào trong khi đứng lên."],"quickTip":"Tư thế chân rộng giúp giảm biên độ di chuyển, phù hợp người có lưng dưới nhạy cảm hơn deadlift thường.","suggestedRestSeconds":150,"imageUrl":"https://images.pexels.com/photos/13822300/pexels-photo-13822300.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"keo-xa-don-nam-rong","name":"Kéo xà đơn nắm rộng","primaryMuscle":"lung_tren","secondaryMuscles":["tay_truoc"],"equipment":["xa_ngang"],"difficulty":"advanced","instructions":["Nắm xà rộng hơn vai, lòng bàn tay hướng ra trước.","Treo người thẳng, siết bả vai trước khi kéo.","Kéo người lên đến khi cằm qua xà, khuỷu tay hướng xuống sau.","Hạ người xuống từ từ đến khi tay gần thẳng."],"commonMistakes":["Đung đưa thân người để lấy đà thay vì dùng lực lưng.","Chỉ kéo được nửa biên độ, không hạ hết tay."],"quickTip":"Nếu chưa kéo được, dùng dây kháng lực hỗ trợ để tập đúng kỹ thuật trước.","suggestedRestSeconds":120,"imageUrl":"https://images.pexels.com/photos/4162478/pexels-photo-4162478.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"keo-xa-don-nam-nguoc","name":"Kéo xà đơn nắm ngược","primaryMuscle":"lung_tren","secondaryMuscles":["tay_truoc"],"equipment":["xa_ngang"],"difficulty":"advanced","instructions":["Nắm xà rộng bằng vai, lòng bàn tay hướng vào người (nắm ngược).","Treo người thẳng, siết bụng và bả vai.","Kéo người lên đến khi cằm qua xà.","Hạ người xuống có kiểm soát, không thả rơi tự do."],"commonMistakes":["Kéo bằng lực tay trước thay vì kích hoạt lưng và tay sau.","Co chân đá lên để lấy đà."],"quickTip":"Nắm ngược giúp tay trước hỗ trợ nhiều hơn, phù hợp cho người mới tập kéo xà.","suggestedRestSeconds":120,"imageUrl":"https://images.pexels.com/photos/3838290/pexels-photo-3838290.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"keo-cap-lung-xo-nam-rong","name":"Kéo cáp lưng xô nắm rộng","primaryMuscle":"lung_tren","secondaryMuscles":["tay_truoc"],"equipment":["may_keo_xo"],"difficulty":"beginner","instructions":["Ngồi vào máy, đùi cố định dưới đệm, nắm thanh kéo rộng hơn vai.","Ngả người ra sau nhẹ, ưỡn ngực.","Kéo thanh xuống đến ngang cằm hoặc ngực trên, siết bả vai.","Trả thanh lên từ từ, giữ tay hơi căng ở điểm cao nhất."],"commonMistakes":["Ngả người ra sau quá nhiều biến thành kéo bằng lưng dưới.","Kéo thanh xuống sau gáy gây căng khớp vai."],"quickTip":"Tập trung cảm nhận lực kéo ở xương bả vai thay vì ở cánh tay.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/6922157/pexels-photo-6922157.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"keo-cap-lung-xo-nam-hep","name":"Kéo cáp lưng xô nắm hẹp","primaryMuscle":"lung_tren","secondaryMuscles":["tay_truoc"],"equipment":["may_keo_xo"],"difficulty":"beginner","instructions":["Ngồi vào máy, nắm tay cầm chữ V hoặc nắm hẹp, lòng bàn tay hướng vào nhau.","Kéo tay cầm xuống ngang ngực, khuỷu tay ép sát thân người.","Siết lưng xô ở điểm thấp nhất trong 1 giây.","Trả tay cầm lên từ từ, kiểm soát tốc độ."],"commonMistakes":["Dùng tay kéo là chính, không siết lưng xô.","Kéo quá nhanh mất kiểm soát ở pha trả tay lên."],"quickTip":"Nắm hẹp giúp biên độ dài hơn, phù hợp cảm nhận rõ lưng xô phần dưới.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/3927026/pexels-photo-3927026.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"cheo-ta-don","name":"Chèo tạ đòn","primaryMuscle":"lung_tren","secondaryMuscles":["tay_truoc","lung_duoi"],"equipment":["ta_doi"],"difficulty":"intermediate","instructions":["Đứng hai chân rộng bằng vai, cúi người về trước khoảng 45 độ, lưng thẳng.","Nắm tạ rộng bằng vai, tay duỗi tự nhiên.","Kéo tạ lên sát bụng dưới, khuỷu tay hướng lên sau.","Hạ tạ xuống từ từ, giữ lưng thẳng suốt bài tập."],"commonMistakes":["Đứng thẳng người dần lên khi mỏi thay vì giữ góc cúi cố định.","Giật tạ bằng lực lưng dưới thay vì kéo bằng lưng trên."],"quickTip":"Siết bụng suốt bài để bảo vệ lưng dưới khi cúi người.","suggestedRestSeconds":120,"imageUrl":"https://images.pexels.com/photos/12890895/pexels-photo-12890895.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"cheo-ta-don-mot-tay","name":"Chèo tạ đơn một tay","primaryMuscle":"lung_tren","secondaryMuscles":["tay_truoc"],"equipment":["ta_don","ghe_tap"],"difficulty":"beginner","instructions":["Chống một tay và một gối lên ghế, lưng giữ thẳng song song sàn.","Tay còn lại cầm tạ, duỗi thẳng xuống dưới vai.","Kéo tạ lên sát hông, khuỷu tay hướng lên sau.","Hạ tạ xuống từ từ, đổi bên sau khi hoàn thành hiệp."],"commonMistakes":["Xoay thân người theo tạ khi kéo lên thay vì giữ lưng cố định.","Kéo tạ ra ngoài quá xa thay vì hướng vào hông."],"quickTip":"Tưởng tượng đang kéo khuỷu tay hướng lên trần nhà để cảm nhận đúng lưng xô.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/14209250/pexels-photo-14209250.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"cheo-ta-don-hai-tay-cui-nguoi","name":"Chèo tạ đơn hai tay cúi người","primaryMuscle":"lung_tren","secondaryMuscles":["tay_truoc","lung_duoi"],"equipment":["ta_don"],"difficulty":"intermediate","instructions":["Đứng hai chân rộng bằng vai, mỗi tay cầm một tạ đơn, cúi người 45 độ.","Giữ lưng thẳng, mắt nhìn xuống sàn phía trước.","Kéo hai tạ lên sát hông cùng lúc, siết bả vai.","Hạ tạ xuống có kiểm soát, không để lưng cong."],"commonMistakes":["Cúi người quá thấp hoặc quá cao làm mất góc chèo hiệu quả.","Dùng tạ quá nặng khiến phải giật người để kéo."],"quickTip":"Nếu lưng dưới yếu, có thể tựa trán vào ghế nghiêng để giảm tải cột sống.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/136410/pexels-photo-136410.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"keo-cap-ngoi","name":"Kéo cáp ngồi","primaryMuscle":"lung_tren","secondaryMuscles":["tay_truoc"],"equipment":["may_keo_xo"],"difficulty":"beginner","instructions":["Ngồi thẳng lưng, chân đạp nhẹ vào bệ, nắm tay cầm chữ V.","Kéo tay cầm về phía bụng, khuỷu tay ép sát thân người.","Siết bả vai lại với nhau ở điểm cuối.","Thả tay cầm ra từ từ, thân người giữ thẳng không đổ về sau."],"commonMistakes":["Đổ người ra sau quá nhiều để kéo được nặng hơn.","Gù lưng ở pha thả tay cầm ra."],"quickTip":"Giữ ngực ưỡn nhẹ suốt bài để lưng trên làm việc đúng vai trò.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/14094850/pexels-photo-14094850.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"cheo-day-khang-luc","name":"Chèo dây kháng lực","primaryMuscle":"lung_tren","secondaryMuscles":["tay_truoc"],"equipment":["day_khang_luc"],"difficulty":"beginner","instructions":["Cố định dây kháng lực phía trước ngang bụng, ngồi hoặc đứng đối diện điểm cố định.","Mỗi tay cầm một đầu dây, tay duỗi thẳng về phía trước.","Kéo hai tay về phía hông, khuỷu tay ép sát thân người.","Trả tay về vị trí ban đầu, giữ dây luôn căng."],"commonMistakes":["Ngồi quá gần điểm cố định làm dây chùng, mất lực cản.","Gù lưng khi kéo thay vì giữ lưng thẳng."],"quickTip":"Bài tập này tiện để tập lưng tại nhà khi không có máy kéo cáp.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/5067749/pexels-photo-5067749.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"keo-xa-don-ho-tro-day-khang-luc","name":"Kéo xà đơn hỗ trợ dây kháng lực","primaryMuscle":"lung_tren","secondaryMuscles":["tay_truoc"],"equipment":["xa_ngang","day_khang_luc"],"difficulty":"beginner","instructions":["Quấn dây kháng lực quanh xà, luồn một đầu dây qua đầu kia tạo vòng.","Đặt một chân hoặc đầu gối vào vòng dây để giảm tải trọng lượng cơ thể.","Kéo người lên như kéo xà thông thường đến khi cằm qua xà.","Hạ người xuống từ từ, giữ dây luôn căng hỗ trợ."],"commonMistakes":["Chọn dây có lực hỗ trợ quá lớn khiến bài tập mất tác dụng.","Đạp chân nhún vào dây để lấy đà thay vì kéo bằng lưng."],"quickTip":"Giảm dần độ hỗ trợ của dây theo thời gian để tiến tới kéo xà không hỗ trợ.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/6339607/pexels-photo-6339607.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"cheo-ta-don-cam-nguoc","name":"Chèo tạ đòn cầm ngược","primaryMuscle":"lung_tren","secondaryMuscles":["tay_truoc"],"equipment":["ta_doi"],"difficulty":"intermediate","instructions":["Đứng cúi người 45 độ, nắm tạ đòn ngược (lòng bàn tay hướng lên), rộng bằng vai.","Giữ lưng thẳng, siết bụng.","Kéo tạ lên sát bụng trên, khuỷu tay ép gần thân người.","Hạ tạ xuống từ từ về vị trí ban đầu."],"commonMistakes":["Đứng thẳng dần lên khi tạ nặng, làm giảm hiệu quả bài tập.","Kéo tạ quá nhanh gây mất kiểm soát ở điểm thấp nhất."],"quickTip":"Cầm ngược giúp tay trước tham gia nhiều hơn, tạo cảm giác khác biệt so với chèo cầm sấp.","suggestedRestSeconds":100,"imageUrl":"https://images.pexels.com/photos/949134/pexels-photo-949134.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"keo-cap-mot-tay","name":"Kéo cáp một tay","primaryMuscle":"lung_tren","secondaryMuscles":["tay_truoc"],"equipment":["may_keo_xo"],"difficulty":"intermediate","instructions":["Ngồi vào máy kéo cáp, chỉnh tay cầm đơn ngang tầm ngực.","Cầm tay cầm bằng một tay, tay còn lại chống nhẹ lên đùi.","Kéo tay cầm về phía hông, xoay nhẹ thân trên theo lực kéo.","Trả tay cầm về vị trí ban đầu có kiểm soát, đổi bên sau khi hết hiệp."],"commonMistakes":["Xoay thân người quá nhiều thay vì để lưng làm việc chính.","Không kéo hết biên độ về phía hông."],"quickTip":"Tập một tay giúp phát hiện và khắc phục sự mất cân bằng lực giữa hai bên lưng.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/5327505/pexels-photo-5327505.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"cheo-ta-don-tu-the-plank","name":"Chèo tạ đơn tư thế plank","primaryMuscle":"lung_tren","secondaryMuscles":["bung","tay_truoc"],"equipment":["ta_don"],"difficulty":"advanced","instructions":["Vào tư thế plank cao, hai tay chống lên hai tạ đơn, chân mở rộng bằng vai để giữ thăng bằng.","Kéo một tạ lên sát hông, giữ hông không xoay theo.","Hạ tạ về sàn có kiểm soát, đổi bên liên tục.","Siết bụng và mông suốt bài để giữ thân người ổn định."],"commonMistakes":["Để hông xoay và võng xuống khi kéo tạ lên.","Chọn tạ quá nặng khiến mất thăng bằng plank."],"quickTip":"Mở rộng chân hơn để tăng độ vững, giảm dần khi đã quen với bài tập.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/2247179/pexels-photo-2247179.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-hong-ta-don-hip-thrust","name":"Nâng hông tạ đòn (Hip Thrust)","primaryMuscle":"mong","secondaryMuscles":["dui_sau"],"equipment":["ta_doi","ghe_tap"],"difficulty":"intermediate","instructions":["Ngồi trên sàn, lưng trên tựa vào mép ghế, thanh đòn đặt ngang hông (có đệm lót).","Đặt hai chân rộng bằng vai, bàn chân sát mông.","Đẩy hông lên cao cho đến khi thân người tạo đường thẳng từ vai đến gối.","Siết chặt mông ở điểm cao nhất, sau đó hạ hông xuống có kiểm soát."],"commonMistakes":["Ưỡn lưng dưới quá mức thay vì đẩy hông bằng lực mông.","Đặt chân quá gần hoặc quá xa mông làm giảm hiệu quả."],"quickTip":"Dùng đệm lót thanh đòn để tránh đau vùng hông khi tập nặng.","suggestedRestSeconds":120,"imageUrl":"https://images.pexels.com/photos/2261483/pexels-photo-2261483.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-hong-ta-don","name":"Nâng hông tạ đơn","primaryMuscle":"mong","secondaryMuscles":["dui_sau"],"equipment":["ta_don","ghe_tap"],"difficulty":"beginner","instructions":["Ngồi trên sàn, lưng trên tựa vào mép ghế, đặt một tạ đơn ngang hông.","Giữ tạ bằng hai tay, đặt hai chân rộng bằng vai.","Đẩy hông lên cao đến khi thân người thẳng hàng từ vai đến gối.","Siết mông rồi hạ hông xuống có kiểm soát."],"commonMistakes":["Không siết mông ở điểm cao nhất, chỉ đẩy hông bằng quán tính.","Để tạ lăn hoặc lệch khỏi vị trí giữa hông."],"quickTip":"Phù hợp thay thế hip thrust tạ đòn khi phòng tập không có đệm lót thanh đòn.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/14099909/pexels-photo-14099909.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-hong-khong-ta-glute-bridge","name":"Nâng hông không tạ (Glute Bridge)","primaryMuscle":"mong","secondaryMuscles":["dui_sau","bung"],"equipment":["khong_dung_cu"],"difficulty":"beginner","instructions":["Nằm ngửa trên sàn, gối gập, hai bàn chân đặt sát mông rộng bằng hông.","Siết bụng và mông, đẩy hông lên cao.","Giữ 1-2 giây ở điểm cao nhất, thân người tạo đường thẳng từ vai đến gối.","Hạ hông xuống từ từ, không chạm sàn hoàn toàn giữa các lần lặp."],"commonMistakes":["Đẩy hông lên quá cao gây ưỡn lưng dưới quá mức.","Dùng lực đùi sau thay vì kích hoạt mông."],"quickTip":"Bài khởi động rất tốt để kích hoạt cơ mông trước khi squat hoặc deadlift.","suggestedRestSeconds":45,"imageUrl":"https://images.pexels.com/photos/36400032/pexels-photo-36400032.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-hong-mot-chan","name":"Nâng hông một chân","primaryMuscle":"mong","secondaryMuscles":["dui_sau","bung"],"equipment":["khong_dung_cu"],"difficulty":"intermediate","instructions":["Nằm ngửa trên sàn, gối gập, một chân duỗi thẳng lên trần hoặc giữ song song sàn.","Chân còn lại đặt sát mông, siết bụng và mông.","Đẩy hông lên cao bằng lực chân trụ duy nhất.","Hạ hông xuống có kiểm soát, hoàn thành hiệp rồi đổi chân."],"commonMistakes":["Xoay hông lệch sang một bên khi đẩy lên.","Dùng chân đang duỗi để hỗ trợ lực đẩy."],"quickTip":"Bài tập một chân giúp phát hiện mất cân bằng lực giữa hai bên mông.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/25596682/pexels-photo-25596682.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"da-chan-sau-bang-day-khang-luc","name":"Đá chân sau bằng dây kháng lực","primaryMuscle":"mong","secondaryMuscles":["dui_sau"],"equipment":["day_khang_luc"],"difficulty":"beginner","instructions":["Quấn dây kháng lực quanh hai mắt cá chân, chống hai tay và hai gối trên sàn.","Giữ lưng thẳng, siết bụng.","Đá thẳng một chân ra sau và lên cao, giữ gối gập nhẹ.","Hạ chân xuống có kiểm soát, hoàn thành hiệp rồi đổi chân."],"commonMistakes":["Ưỡn lưng dưới quá mức khi đá chân lên cao.","Đá chân quá nhanh dùng đà thay vì kiểm soát bằng cơ mông."],"quickTip":"Siết bụng suốt bài để tránh lưng dưới phải bù trừ lực.","suggestedRestSeconds":45,"imageUrl":"https://images.pexels.com/photos/4148956/pexels-photo-4148956.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"da-chan-sau-tren-may-cap","name":"Đá chân sau trên máy cáp","primaryMuscle":"mong","secondaryMuscles":["dui_sau"],"equipment":["may_keo_xo"],"difficulty":"intermediate","instructions":["Gắn dây cáp vào cổ chân, đứng đối diện máy, hai tay vịn nhẹ vào khung máy.","Giữ thân người ổn định, chân trụ hơi khuỵu.","Đá thẳng chân gắn dây ra sau và lên cao.","Trả chân về vị trí ban đầu có kiểm soát, hoàn thành hiệp rồi đổi bên."],"commonMistakes":["Đổ người về trước quá nhiều để đá chân cao hơn.","Dùng đà lắc hông thay vì kiểm soát bằng cơ mông."],"quickTip":"Máy cáp giữ lực căng liên tục, hiệu quả hơn đá chân không tạ khi đã quen bài tập.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/4807549/pexels-photo-4807549.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"da-chan-sau-khong-ta-donkey-kick","name":"Đá chân sau không tạ (Donkey Kick)","primaryMuscle":"mong","secondaryMuscles":["dui_sau"],"equipment":["khong_dung_cu"],"difficulty":"beginner","instructions":["Chống hai tay và hai gối trên sàn, lưng giữ thẳng tự nhiên.","Giữ gối gập 90 độ, đá một chân lên cao về phía trần nhà.","Siết mông ở điểm cao nhất.","Hạ gối về gần sàn có kiểm soát, hoàn thành hiệp rồi đổi chân."],"commonMistakes":["Ưỡn lưng dưới để đá chân cao hơn.","Duỗi thẳng chân thay vì giữ gối gập 90 độ."],"quickTip":"Tập chậm và siết chặt ở điểm cao nhất quan trọng hơn đá nhanh nhiều lần.","suggestedRestSeconds":45,"imageUrl":"https://images.pexels.com/photos/8472148/pexels-photo-8472148.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"buoc-tan-kieu-curtsy","name":"Bước tấn kiểu Curtsy","primaryMuscle":"mong","secondaryMuscles":["dui_truoc"],"equipment":["ta_don"],"difficulty":"intermediate","instructions":["Đứng thẳng, mỗi tay cầm tạ đơn hoặc không cầm tạ nếu mới tập.","Bước một chân ra sau chéo qua chân trụ như động tác cúi chào.","Hạ người xuống đến khi gối chân sau gần chạm sàn.","Đẩy người trở lại vị trí đứng ban đầu, hoàn thành hiệp rồi đổi chân."],"commonMistakes":["Xoay hông quá nhiều làm mất thăng bằng.","Bước chân chéo không đủ xa khiến bài tập mất tác dụng lên mông."],"quickTip":"Bài tập tốt để nhắm vào phần cơ mông bên ngoài (gluteus medius).","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/4587359/pexels-photo-4587359.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"squat-chan-rong-sumo-squat","name":"Squat chân rộng (Sumo Squat)","primaryMuscle":"mong","secondaryMuscles":["dui_truoc"],"equipment":["ta_doi"],"difficulty":"intermediate","instructions":["Đứng chân rộng hơn vai, mũi chân hướng chéo ra ngoài, tạ đòn đặt trên lưng trên.","Siết bụng, hạ người xuống thẳng giữa hai chân.","Hạ đến khi đùi song song sàn, đầu gối hướng theo mũi chân.","Đứng thẳng dậy trở lại, siết mông ở điểm cao nhất."],"commonMistakes":["Đầu gối đổ vào trong thay vì hướng theo mũi chân.","Chân chưa đủ rộng khiến bài tập giống squat thường."],"quickTip":"Tư thế chân rộng và mũi chân mở giúp nhắm nhiều hơn vào mông và đùi trong.","suggestedRestSeconds":120,"imageUrl":"https://images.pexels.com/photos/1552249/pexels-photo-1552249.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"di-bo-cua-bang-day-khang-luc","name":"Đi bộ cua bằng dây kháng lực","primaryMuscle":"mong","secondaryMuscles":[],"equipment":["day_khang_luc"],"difficulty":"beginner","instructions":["Quấn dây kháng lực quanh hai mắt cá chân hoặc trên đầu gối, đứng chân rộng bằng hông.","Hạ người xuống tư thế squat nhẹ (half squat), giữ nguyên độ hạ suốt bài.","Bước sang ngang từng bước nhỏ, giữ dây luôn căng.","Bước đủ số bước quy định rồi đổi hướng ngược lại."],"commonMistakes":["Đứng thẳng người lên trong lúc bước làm mất lực căng của dây.","Bước quá dài khiến đầu gối xoay lệch."],"quickTip":"Bài khởi động phổ biến trước buổi tập chân để kích hoạt cơ mông ngoài.","suggestedRestSeconds":45,"imageUrl":"https://images.pexels.com/photos/5163843/pexels-photo-5163843.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-chan-sang-ngang-nam-nghieng","name":"Nâng chân sang ngang nằm nghiêng","primaryMuscle":"mong","secondaryMuscles":[],"equipment":["khong_dung_cu"],"difficulty":"beginner","instructions":["Nằm nghiêng một bên trên thảm, chân dưới gập nhẹ để giữ thăng bằng.","Chân trên duỗi thẳng, giữ hông vuông góc với sàn.","Nâng chân trên lên cao hết mức có thể mà không xoay hông ra sau.","Hạ chân xuống từ từ, hoàn thành hiệp rồi đổi bên."],"commonMistakes":["Xoay hông ra sau để nâng chân cao hơn.","Dùng đà đá chân thay vì nâng có kiểm soát."],"quickTip":"Bài tập nhẹ nhàng phù hợp làm khởi động hoặc tập bổ trợ cuối buổi.","suggestedRestSeconds":45,"imageUrl":"https://images.pexels.com/photos/7530016/pexels-photo-7530016.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"dap-dui-tren-may-hip-abduction","name":"Đạp đùi trên máy (Hip Abduction)","primaryMuscle":"mong","secondaryMuscles":[],"equipment":["may_tap_chan"],"difficulty":"beginner","instructions":["Ngồi vào máy, đặt hai chân vào đệm chặn phía ngoài đùi.","Lưng tựa chắc vào ghế, hai tay nắm tay cầm hai bên.","Đẩy hai chân mở rộng ra ngoài hết mức có thể.","Khép chân trở lại từ từ về vị trí ban đầu."],"commonMistakes":["Dùng đà thân trên để đẩy chân ra thay vì lực cơ mông.","Khép chân quá nhanh mất kiểm soát."],"quickTip":"Máy cô lập tốt phần cơ mông bên ngoài, phù hợp tập cuối buổi chân.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/6539849/pexels-photo-6539849.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"day-nguc-ta-don-tren-ghe-phang","name":"Đẩy ngực tạ đòn trên ghế phẳng","primaryMuscle":"nguc","secondaryMuscles":["tay_sau","vai_truoc"],"equipment":["ta_doi","ghe_tap"],"difficulty":"intermediate","instructions":["Nằm ngửa trên ghế phẳng, hai chân đặt vững trên sàn, mắt ngay dưới thanh đòn.","Nắm tạ rộng hơn vai một chút, hạ thanh đòn xuống chạm nhẹ giữa ngực.","Đẩy thanh đòn thẳng lên trên vai cho đến khi tay gần thẳng, không khóa cứng khuỷu tay.","Hít vào khi hạ tạ, thở ra khi đẩy lên."],"commonMistakes":["Nảy tạ trên ngực để lấy đà thay vì kiểm soát chuyển động.","Đẩy tạ lệch về phía mặt hoặc bụng thay vì thẳng trên vai."],"quickTip":"Siết bả vai xuống ghế và giữ lưng hơi ưỡn tự nhiên để bảo vệ vai.","suggestedRestSeconds":120,"imageUrl":"https://images.pexels.com/photos/12752465/pexels-photo-12752465.png?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"day-nguc-ta-don-tren-ghe-phang-2","name":"Đẩy ngực tạ đơn trên ghế phẳng","primaryMuscle":"nguc","secondaryMuscles":["tay_sau","vai_truoc"],"equipment":["ta_don","ghe_tap"],"difficulty":"beginner","instructions":["Nằm ngửa trên ghế phẳng, mỗi tay cầm một quả tạ đơn ngang ngực.","Đẩy hai tạ lên thẳng phía trên vai cho đến khi tay gần thẳng.","Hạ tạ xuống từ từ đến khi khuỷu tay ngang ghế, giữ cổ tay thẳng.","Lặp lại đều nhịp, không để tạ va chạm nhau ở đỉnh chuyển động."],"commonMistakes":["Hạ tạ quá sâu khiến vai bị kéo căng quá mức.","Để hai tay tách quá rộng làm mất lực đẩy vào ngực."],"quickTip":"Dùng tạ đơn giúp mỗi bên ngực làm việc độc lập, tốt để cân bằng lực hai bên.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/3839310/pexels-photo-3839310.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"day-nguc-ta-don-ghe-nghieng","name":"Đẩy ngực tạ đòn ghế nghiêng","primaryMuscle":"nguc","secondaryMuscles":["vai_truoc","tay_sau"],"equipment":["ta_doi","ghe_tap"],"difficulty":"intermediate","instructions":["Chỉnh ghế nghiêng khoảng 30-45 độ, nằm ngửa và nắm tạ rộng hơn vai.","Hạ thanh đòn xuống chạm nhẹ phần ngực trên, gần xương đòn.","Đẩy tạ thẳng lên trên, hướng nhẹ về phía đầu theo góc ghế.","Kiểm soát tốc độ hạ tạ, tránh để tạ rơi nhanh."],"commonMistakes":["Chỉnh ghế nghiêng quá cao (trên 45 độ) làm bài tập ngả sang vai trước.","Chống chân không vững khiến mất thăng bằng khi đẩy nặng."],"quickTip":"Góc ghế 30 độ là đủ để nhắm vào ngực trên mà không lấn sang vai quá nhiều.","suggestedRestSeconds":120,"imageUrl":"https://images.pexels.com/photos/4047156/pexels-photo-4047156.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"day-nguc-ta-don-ghe-nghieng-2","name":"Đẩy ngực tạ đơn ghế nghiêng","primaryMuscle":"nguc","secondaryMuscles":["vai_truoc","tay_sau"],"equipment":["ta_don","ghe_tap"],"difficulty":"beginner","instructions":["Chỉnh ghế nghiêng 30-45 độ, ngồi tựa lưng, mỗi tay cầm một tạ đơn ngang vai.","Đẩy tạ lên trên theo hướng chéo, hai tạ gần chạm nhau ở đỉnh.","Hạ tạ xuống từ từ đến khi khuỷu tay ngang vai.","Giữ core siết chặt trong suốt bài tập."],"commonMistakes":["Đẩy tạ thẳng đứng thay vì theo hướng vai, làm giảm hiệu quả lên ngực trên.","Dùng tạ quá nặng khiến biên độ chuyển động bị rút ngắn."],"quickTip":"Ưu tiên biên độ đầy đủ với tạ vừa sức hơn là tạ nặng nhưng cụt biên độ.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/18060077/pexels-photo-18060077.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"day-nguc-ta-don-ghe-doc-xuong","name":"Đẩy ngực tạ đơn ghế dốc xuống","primaryMuscle":"nguc","secondaryMuscles":["tay_sau"],"equipment":["ta_don","ghe_tap"],"difficulty":"intermediate","instructions":["Chỉnh ghế dốc xuống nhẹ (đầu thấp hơn chân) hoặc nằm ghế phẳng với chân kê cao.","Cầm tạ đơn ngang ngực dưới, giữ chặt phần thân trên.","Đẩy tạ lên trên theo hướng thẳng, tập trung lực vào ngực dưới.","Hạ tạ chậm rãi về vị trí ban đầu."],"commonMistakes":["Chỉnh độ dốc quá lớn gây khó chịu vùng đầu và cổ.","Không siết core khiến lưng dưới bị ưỡn quá mức."],"quickTip":"Nếu không có ghế dốc chuyên dụng, kê chân cao trên ghế phẳng là đủ hiệu quả.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/38576478/pexels-photo-38576478.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"ep-nguc-ta-don","name":"Ép ngực tạ đơn","primaryMuscle":"nguc","secondaryMuscles":["vai_truoc"],"equipment":["ta_don","ghe_tap"],"difficulty":"intermediate","instructions":["Nằm ngửa trên ghế phẳng, hai tay cầm tạ đơn duỗi thẳng trên ngực, lòng bàn tay hướng vào nhau.","Hạ tạ sang hai bên theo cung tròn, khuỷu tay hơi gập cố định.","Hạ đến khi cảm nhận ngực căng nhẹ, không hạ quá sâu gây đau vai.","Khép tay lại theo đúng cung tròn ban đầu để về vị trí trên ngực."],"commonMistakes":["Gập duỗi khuỷu tay như đang đẩy tạ thay vì giữ cố định để ép ngực.","Dùng tạ quá nặng làm mất kiểm soát ở điểm thấp nhất."],"quickTip":"Tưởng tượng đang ôm một thân cây lớn để giữ đúng quỹ đạo cung tròn.","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/18060076/pexels-photo-18060076.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"ep-nguc-ta-don-ghe-nghieng","name":"Ép ngực tạ đơn ghế nghiêng","primaryMuscle":"nguc","secondaryMuscles":["vai_truoc"],"equipment":["ta_don","ghe_tap"],"difficulty":"intermediate","instructions":["Chỉnh ghế nghiêng 30 độ, nằm tựa lưng, hai tay cầm tạ duỗi thẳng trên ngực trên.","Hạ tạ sang hai bên theo cung tròn, khuỷu tay hơi gập cố định.","Ép ngực để khép tay về vị trí ban đầu.","Giữ nhịp thở đều, không nín thở khi ép tạ."],"commonMistakes":["Chỉnh ghế quá cao khiến bài tập thiên về vai thay vì ngực trên.","Ép tạ quá nhanh làm mất kiểm soát biên độ chuyển động."],"quickTip":"Dùng tạ nhẹ hơn bài đẩy để giữ đúng kỹ thuật cung tròn.","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/18060023/pexels-photo-18060023.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"day-nguc-tren-may","name":"Đẩy ngực trên máy","primaryMuscle":"nguc","secondaryMuscles":["tay_sau","vai_truoc"],"equipment":["may_tap_nguc"],"difficulty":"beginner","instructions":["Ngồi vào máy, chỉnh độ cao ghế sao cho tay cầm ngang ngực.","Nắm hai tay cầm, lưng tựa chắc vào đệm.","Đẩy tay cầm về phía trước cho đến khi tay gần thẳng, không khóa khớp khuỷu.","Từ từ trả lại về vị trí ban đầu theo kiểm soát."],"commonMistakes":["Chỉnh ghế sai độ cao khiến tay cầm không ngang ngực.","Đẩy quá nhanh, dựa vào đà thay vì lực cơ ngực."],"quickTip":"Máy tập ngực phù hợp để làm nóng cơ hoặc tập khi mới bắt đầu vì dễ kiểm soát quỹ đạo.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/6539838/pexels-photo-6539838.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"ep-nguc-tren-may-pec-deck","name":"Ép ngực trên máy (Pec Deck)","primaryMuscle":"nguc","secondaryMuscles":["vai_truoc"],"equipment":["may_tap_nguc"],"difficulty":"beginner","instructions":["Ngồi vào máy, lưng tựa thẳng, tay đặt lên đệm hoặc nắm tay cầm ngang vai.","Khép hai tay vào nhau ở phía trước ngực theo cung tròn.","Giữ 1 giây khi hai tay gần chạm nhau, siết chặt cơ ngực.","Mở tay trở lại từ từ, không để đệm va mạnh vào khung máy."],"commonMistakes":["Dùng đà thân trên để đẩy tay thay vì lực cơ ngực.","Mở tay quá rộng ra sau gây căng khớp vai."],"quickTip":"Siết và giữ 1 giây ở điểm khép tay để tăng hiệu quả kích hoạt cơ ngực.","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/3768913/pexels-photo-3768913.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"chong-day","name":"Chống đẩy","primaryMuscle":"nguc","secondaryMuscles":["tay_sau","bung"],"equipment":["khong_dung_cu"],"difficulty":"beginner","instructions":["Chống hai tay xuống sàn rộng hơn vai một chút, cơ thể tạo thành đường thẳng từ đầu đến gót chân.","Hạ người xuống đến khi ngực gần chạm sàn, khuỷu tay hướng chéo ra sau.","Đẩy người lên trở lại vị trí ban đầu, siết chặt bụng và mông.","Giữ đầu thẳng hàng với cột sống trong suốt bài tập."],"commonMistakes":["Để hông võng xuống hoặc nhô cao làm sai tư thế plank.","Chỉ hạ người một nửa biên độ, không chạm gần sàn."],"quickTip":"Nếu chưa đủ sức, chống đầu gối xuống sàn để giảm tải mà vẫn giữ đúng kỹ thuật.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/4775232/pexels-photo-4775232.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"chong-day-chan-cao","name":"Chống đẩy chân cao","primaryMuscle":"nguc","secondaryMuscles":["vai_truoc","tay_sau"],"equipment":["khong_dung_cu","ghe_tap"],"difficulty":"intermediate","instructions":["Đặt hai chân lên ghế, hai tay chống xuống sàn rộng hơn vai.","Giữ cơ thể thẳng hàng từ vai đến gót chân.","Hạ ngực xuống gần sàn rồi đẩy người lên trở lại.","Siết bụng để tránh hông bị võng trong suốt chuyển động."],"commonMistakes":["Kê chân quá cao khi chưa đủ sức, làm mất kiểm soát tư thế.","Đẩy người lên không hết biên độ, khuỷu tay còn gập."],"quickTip":"Chân càng cao thì phần ngực trên và vai càng phải làm việc nhiều hơn.","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/8401198/pexels-photo-8401198.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"chong-day-tay-rong","name":"Chống đẩy tay rộng","primaryMuscle":"nguc","secondaryMuscles":["vai_truoc"],"equipment":["khong_dung_cu"],"difficulty":"beginner","instructions":["Chống hai tay xuống sàn rộng hơn vai khoảng 1.5 lần so với chống đẩy thường.","Hạ người xuống đến khi ngực gần chạm sàn.","Đẩy người lên, tập trung siết cơ ngực ở điểm cao nhất.","Giữ thân người thẳng, không để hông chùng xuống."],"commonMistakes":["Chống tay quá rộng gây căng khớp vai và cổ tay.","Hạ người quá nhanh, không kiểm soát tốc độ."],"quickTip":"Tay càng rộng thì biên độ càng ngắn nhưng cơ ngực ngoài được kích hoạt nhiều hơn.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/4803878/pexels-photo-4803878.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"day-nguc-bang-day-khang-luc","name":"Đẩy ngực bằng dây kháng lực","primaryMuscle":"nguc","secondaryMuscles":["tay_sau","vai_truoc"],"equipment":["day_khang_luc"],"difficulty":"beginner","instructions":["Cố định dây kháng lực phía sau lưng ngang ngực (cột, cửa, hoặc quấn quanh vật chắc chắn).","Mỗi tay cầm một đầu dây, đứng chân trước chân sau để giữ thăng bằng.","Đẩy hai tay về phía trước cho đến khi tay gần thẳng.","Từ từ đưa tay trở lại vị trí ban đầu, giữ dây luôn căng."],"commonMistakes":["Đứng quá gần điểm cố định làm dây bị chùng, mất lực cản.","Ưỡn lưng quá mức để lấy đà đẩy."],"quickTip":"Chọn dây có độ căng vừa đủ để hoàn thành hết biên độ mà vẫn kiểm soát được.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/15917308/pexels-photo-15917308.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"ep-nguc-bang-day-khang-luc","name":"Ép ngực bằng dây kháng lực","primaryMuscle":"nguc","secondaryMuscles":["vai_truoc"],"equipment":["day_khang_luc"],"difficulty":"beginner","instructions":["Cố định dây kháng lực phía sau ngang vai, mỗi tay cầm một đầu dây, hai tay dang ngang.","Bước một chân lên trước để tạo thế vững.","Khép hai tay lại phía trước ngực theo cung tròn.","Mở tay trở lại từ từ, giữ dây luôn căng trong suốt bài tập."],"commonMistakes":["Gập khuỷu tay quá nhiều biến bài ép thành bài đẩy.","Thả lỏng dây ở điểm mở tay khiến mất lực cản."],"quickTip":"Giữ khuỷu tay hơi cong cố định trong suốt bài để cơ ngực làm việc đúng vai trò.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/6667512/pexels-photo-6667512.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"day-ta-sau-dau-ta-don-hai-tay","name":"Đẩy tạ sau đầu tạ đơn hai tay","primaryMuscle":"tay_sau","secondaryMuscles":[],"equipment":["ta_don"],"difficulty":"intermediate","instructions":["Ngồi hoặc đứng thẳng, hai tay cùng cầm một tạ đơn, nâng thẳng lên qua đầu.","Gập khuỷu tay hạ tạ xuống sau đầu, khuỷu tay hướng lên trần nhà.","Duỗi thẳng tay trở lại vị trí trên đầu.","Giữ khuỷu tay cố định gần đầu trong suốt bài tập."],"commonMistakes":["Để khuỷu tay mở rộng ra hai bên thay vì hướng thẳng lên.","Hạ tạ quá thấp gây căng khớp vai và khuỷu tay."],"quickTip":"Siết bụng để tránh ưỡn lưng khi nâng tạ qua đầu.","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/6388359/pexels-photo-6388359.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"day-ta-sau-dau-ta-don-mot-tay","name":"Đẩy tạ sau đầu tạ đơn một tay","primaryMuscle":"tay_sau","secondaryMuscles":[],"equipment":["ta_don"],"difficulty":"intermediate","instructions":["Đứng hoặc ngồi thẳng, một tay cầm tạ đơn nâng thẳng lên qua đầu.","Tay còn lại có thể đỡ nhẹ khuỷu tay đang tập để giữ ổn định.","Gập khuỷu tay hạ tạ xuống sau đầu, sau đó duỗi thẳng trở lại.","Hoàn thành hiệp rồi đổi bên."],"commonMistakes":["Để khuỷu tay đổ ra ngoài thay vì hướng thẳng lên trần.","Dùng tạ quá nặng khiến vai phải bù trừ lực."],"quickTip":"Tập một tay giúp phát hiện và khắc phục mất cân bằng sức mạnh giữa hai bên tay sau.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/18060079/pexels-photo-18060079.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"day-nguc-ta-don-nam-hep","name":"Đẩy ngực tạ đòn nắm hẹp","primaryMuscle":"tay_sau","secondaryMuscles":["nguc"],"equipment":["ta_doi","ghe_tap"],"difficulty":"intermediate","instructions":["Nằm ngửa trên ghế phẳng, nắm tạ đòn hẹp hơn vai một chút.","Hạ thanh đòn xuống chạm ngực dưới, khuỷu tay ép sát thân người.","Đẩy tạ lên thẳng trên vai, tập trung lực vào tay sau.","Hạ tạ xuống có kiểm soát, không để khuỷu tay mở rộng ra ngoài."],"commonMistakes":["Nắm tay quá hẹp gây căng khớp cổ tay và khuỷu tay.","Để khuỷu tay mở rộng ra ngoài làm bài tập chuyển thành đẩy ngực thường."],"quickTip":"Nắm tay bằng khoảng vai hoặc hẹp hơn một chút, không cần quá hẹp để tránh chấn thương cổ tay.","suggestedRestSeconds":100,"imageUrl":"https://images.pexels.com/photos/3837743/pexels-photo-3837743.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"duoi-tay-sau-bang-cap","name":"Duỗi tay sau bằng cáp","primaryMuscle":"tay_sau","secondaryMuscles":[],"equipment":["may_keo_xo"],"difficulty":"beginner","instructions":["Đứng đối diện máy cáp, nắm thanh tay cầm thẳng rộng bằng vai.","Giữ khuỷu tay sát thân người, đẩy tay cầm xuống đến khi tay gần thẳng.","Giữ 1 giây ở điểm thấp nhất, siết tay sau.","Trả tay cầm lên từ từ, giữ khuỷu tay cố định."],"commonMistakes":["Đưa khuỷu tay ra khỏi thân người khi đẩy xuống.","Dùng thân trên đổ về trước để lấy đà."],"quickTip":"Chỉ có cẳng tay di chuyển, khuỷu tay giữ như bản lề cố định suốt bài tập.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/17559311/pexels-photo-17559311.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"duoi-tay-sau-bang-cap-day-thung","name":"Duỗi tay sau bằng cáp dây thừng","primaryMuscle":"tay_sau","secondaryMuscles":[],"equipment":["may_keo_xo"],"difficulty":"beginner","instructions":["Đứng đối diện máy cáp, nắm hai đầu dây thừng, khuỷu tay sát thân người.","Đẩy dây thừng xuống, tách hai đầu dây ra ngoài ở điểm thấp nhất.","Giữ 1 giây, siết chặt tay sau.","Trả dây lên từ từ về vị trí ban đầu."],"commonMistakes":["Không tách dây thừng ở điểm thấp, giảm hiệu quả co cơ.","Cúi người quá nhiều để đẩy dây xuống."],"quickTip":"Dây thừng cho phép xoay cổ tay tự nhiên, giúp cô lập tay sau tốt hơn thanh thẳng.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/5327498/pexels-photo-5327498.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"duoi-tay-sau-ta-don-cui-nguoi","name":"Duỗi tay sau tạ đơn cúi người","primaryMuscle":"tay_sau","secondaryMuscles":[],"equipment":["ta_don","ghe_tap"],"difficulty":"intermediate","instructions":["Chống một tay và một gối lên ghế, lưng giữ song song sàn.","Tay còn lại cầm tạ, khuỷu tay gập 90 độ sát thân người.","Duỗi thẳng cẳng tay ra sau đến khi tay gần thẳng hoàn toàn.","Gập tay trở lại 90 độ, giữ khuỷu tay cố định không hạ xuống."],"commonMistakes":["Hạ khuỷu tay xuống trong lúc duỗi, mất góc cố định 90 độ.","Dùng đà vung tay thay vì duỗi có kiểm soát."],"quickTip":"Giữ cẳng tay trên song song sàn trong suốt bài, chỉ cẳng tay dưới di chuyển.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/19025674/pexels-photo-19025674.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"chong-day-tay-hep-diamond-push-up","name":"Chống đẩy tay hẹp (Diamond Push-up)","primaryMuscle":"tay_sau","secondaryMuscles":["nguc"],"equipment":["khong_dung_cu"],"difficulty":"intermediate","instructions":["Chống hai tay xuống sàn sát nhau, ngón cái và ngón trỏ hai tay chạm nhau tạo hình kim cương.","Giữ thân người thẳng từ đầu đến gót chân.","Hạ ngực xuống gần chạm tay, khuỷu tay ép sát thân người.","Đẩy người lên trở lại vị trí ban đầu."],"commonMistakes":["Để khuỷu tay mở rộng ra ngoài thay vì ép sát thân người.","Hông võng xuống làm sai tư thế plank."],"quickTip":"Nếu chưa đủ sức, chống đầu gối xuống sàn để giảm tải mà vẫn giữ đúng kỹ thuật.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/7187898/pexels-photo-7187898.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nhung-nguoi-tren-ghe-bench-dip","name":"Nhúng người trên ghế (Bench Dip)","primaryMuscle":"tay_sau","secondaryMuscles":["vai_truoc"],"equipment":["ghe_tap"],"difficulty":"beginner","instructions":["Ngồi trên mép ghế, hai tay chống xuống ghế cạnh hông, chân duỗi thẳng ra trước.","Di chuyển hông ra khỏi ghế, hạ người xuống bằng cách gập khuỷu tay.","Hạ đến khi khuỷu tay gập khoảng 90 độ.","Đẩy người lên trở lại vị trí ban đầu bằng lực tay sau."],"commonMistakes":["Hạ người quá thấp gây căng khớp vai.","Để vai nhô lên gần tai thay vì giữ thả lỏng."],"quickTip":"Co gối lại gần ghế để giảm độ khó nếu bài tập chuẩn còn quá nặng.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/4803875/pexels-photo-4803875.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"day-ta-don-ez-nam-skull-crusher","name":"Đẩy tạ đòn EZ nằm (Skull Crusher)","primaryMuscle":"tay_sau","secondaryMuscles":[],"equipment":["ta_doi","ghe_tap"],"difficulty":"advanced","instructions":["Nằm ngửa trên ghế phẳng, nắm tạ đòn EZ, tay duỗi thẳng trên vai.","Gập khuỷu tay hạ tạ xuống gần trán, giữ khuỷu tay cố định hướng lên trần.","Duỗi thẳng tay trở lại vị trí ban đầu.","Kiểm soát tốc độ hạ tạ, tránh để tạ rơi quá nhanh gần đầu."],"commonMistakes":["Để khuỷu tay di chuyển ra trước hoặc ra sau thay vì cố định.","Dùng tạ quá nặng gây mất kiểm soát gần vùng đầu."],"quickTip":"Luôn có người hỗ trợ (spotter) khi tập nặng vì tạ di chuyển gần vùng đầu.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/12775400/pexels-photo-12775400.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"duoi-tay-sau-bang-day-khang-luc","name":"Duỗi tay sau bằng dây kháng lực","primaryMuscle":"tay_sau","secondaryMuscles":[],"equipment":["day_khang_luc"],"difficulty":"beginner","instructions":["Cố định dây kháng lực phía trên cao (cửa, cột), đứng quay lưng lại điểm cố định.","Nắm dây bằng hai tay, khuỷu tay gập sát đầu.","Duỗi thẳng tay xuống dưới trước mặt.","Trả tay về vị trí ban đầu từ từ, giữ dây luôn căng."],"commonMistakes":["Mở rộng khuỷu tay ra hai bên thay vì giữ sát đầu.","Đứng quá gần điểm cố định làm dây chùng."],"quickTip":"Có thể thực hiện từng tay một để tăng độ tập trung vào tay sau.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/6295978/pexels-photo-6295978.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"duoi-tay-sau-cap-mot-tay","name":"Duỗi tay sau cáp một tay","primaryMuscle":"tay_sau","secondaryMuscles":[],"equipment":["may_keo_xo"],"difficulty":"intermediate","instructions":["Đứng quay lưng về phía máy cáp, một tay cầm tay cầm đơn, khuỷu tay gập sát đầu.","Duỗi thẳng tay về phía trước xuống dưới.","Giữ 1 giây ở điểm duỗi thẳng, siết tay sau.","Trả tay về vị trí ban đầu từ từ, đổi bên sau khi hết hiệp."],"commonMistakes":["Để khuỷu tay rời khỏi vị trí sát đầu khi duỗi.","Xoay thân người để lấy đà thay vì duỗi bằng lực tay sau."],"quickTip":"Máy cáp giữ lực căng liên tục, giúp cảm nhận rõ cơ tay sau hơn tạ đơn ở tư thế này.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/20556197/pexels-photo-20556197.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"duoi-tay-sau-cap-nam-nguoc","name":"Duỗi tay sau cáp nắm ngược","primaryMuscle":"tay_sau","secondaryMuscles":[],"equipment":["may_keo_xo"],"difficulty":"intermediate","instructions":["Đứng đối diện máy cáp, nắm thanh tay cầm thẳng bằng cách lòng bàn tay hướng lên (nắm ngược).","Giữ khuỷu tay sát thân người, đẩy tay cầm xuống đến khi tay gần thẳng.","Giữ 1 giây ở điểm thấp nhất.","Trả tay cầm lên từ từ, giữ khuỷu tay cố định."],"commonMistakes":["Xoay cổ tay giữa chừng thay vì giữ nắm ngược cố định.","Dùng thân trên đổ về trước để lấy đà."],"quickTip":"Nắm ngược nhấn mạnh hơn vào phần đầu dài của cơ tay sau so với nắm thường.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/14423610/pexels-photo-14423610.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"cuon-ta-don-dung","name":"Cuốn tạ đòn đứng","primaryMuscle":"tay_truoc","secondaryMuscles":[],"equipment":["ta_doi"],"difficulty":"beginner","instructions":["Đứng thẳng, nắm tạ đòn rộng bằng vai, tay duỗi trước đùi.","Giữ khuỷu tay sát thân người, cuốn tạ lên đến ngang vai.","Giữ 1 giây ở điểm cao nhất, siết cơ tay trước.","Hạ tạ xuống từ từ về vị trí ban đầu."],"commonMistakes":["Đung đưa thân người và hông để lấy đà cuốn tạ lên.","Đẩy khuỷu tay ra trước thay vì giữ cố định sát thân người."],"quickTip":"Nếu phải đung đưa người mới cuốn được tạ lên, đó là dấu hiệu tạ quá nặng.","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/9361335/pexels-photo-9361335.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"cuon-ta-don-dung-2","name":"Cuốn tạ đơn đứng","primaryMuscle":"tay_truoc","secondaryMuscles":[],"equipment":["ta_don"],"difficulty":"beginner","instructions":["Đứng thẳng, mỗi tay cầm tạ đơn, lòng bàn tay hướng ra trước.","Giữ khuỷu tay sát thân người, cuốn hai tạ lên đồng thời.","Giữ 1 giây ở điểm cao nhất.","Hạ tạ xuống từ từ về vị trí ban đầu."],"commonMistakes":["Xoay cổ tay không hết khiến lực không tập trung vào tay trước.","Hạ tạ quá nhanh, mất kiểm soát pha âm."],"quickTip":"Xoay cổ tay để lòng bàn tay hướng lên hoàn toàn ở điểm cao nhất để tối ưu co cơ.","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/3763115/pexels-photo-3763115.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"cuon-ta-don-luan-phien","name":"Cuốn tạ đơn luân phiên","primaryMuscle":"tay_truoc","secondaryMuscles":[],"equipment":["ta_don"],"difficulty":"beginner","instructions":["Đứng thẳng, mỗi tay cầm tạ đơn thả tự nhiên hai bên đùi.","Cuốn tạ bên phải lên ngang vai trong khi tay trái giữ nguyên.","Hạ tay phải xuống đồng thời cuốn tay trái lên, luân phiên đều nhịp.","Giữ thân người thẳng, không xoay hông theo tay đang cuốn."],"commonMistakes":["Xoay hông và vai theo tay đang cuốn để lấy đà.","Không hạ tạ hết biên độ trước khi cuốn tay tiếp theo."],"quickTip":"Luân phiên tay giúp tập trung hơn vào từng bên, dễ phát hiện bên yếu hơn.","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/3917659/pexels-photo-3917659.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"cuon-ta-don-kieu-bua","name":"Cuốn tạ đơn kiểu búa","primaryMuscle":"tay_truoc","secondaryMuscles":[],"equipment":["ta_don"],"difficulty":"beginner","instructions":["Đứng thẳng, mỗi tay cầm tạ đơn, lòng bàn tay hướng vào thân người (như cầm búa).","Giữ khuỷu tay sát thân người, cuốn tạ lên ngang vai.","Giữ 1 giây ở điểm cao nhất.","Hạ tạ xuống từ từ về vị trí ban đầu."],"commonMistakes":["Xoay cổ tay trong lúc cuốn thay vì giữ nguyên góc cầm búa.","Dùng vai để hất tạ lên khi tạ quá nặng."],"quickTip":"Bài này tác động thêm vào cơ cẳng tay, tốt để tăng lực nắm tổng thể.","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/917660/pexels-photo-917660.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"cuon-ta-don-ghe-scott","name":"Cuốn tạ đơn ghế Scott","primaryMuscle":"tay_truoc","secondaryMuscles":[],"equipment":["ta_don","ghe_tap"],"difficulty":"intermediate","instructions":["Ngồi vào ghế Scott, tựa mặt sau cánh tay lên đệm nghiêng, nách sát mép đệm.","Cầm tạ đơn, tay duỗi gần thẳng.","Cuốn tạ lên ngang vai, giữ cánh tay trên áp chặt đệm.","Hạ tạ xuống từ từ nhưng không duỗi thẳng hoàn toàn để tránh áp lực lên khớp khuỷu."],"commonMistakes":["Nhấc cánh tay trên khỏi đệm khi cuốn tạ nặng.","Duỗi tay quá thẳng ở điểm thấp nhất gây căng khớp khuỷu."],"quickTip":"Ghế Scott loại bỏ hoàn toàn khả năng dùng đà, rất tốt để tập trung cô lập tay trước.","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/12314077/pexels-photo-12314077.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"cuon-ta-don-ez","name":"Cuốn tạ đòn EZ","primaryMuscle":"tay_truoc","secondaryMuscles":[],"equipment":["ta_doi"],"difficulty":"beginner","instructions":["Đứng thẳng, nắm tạ đòn ở phần tay cầm chéo (gờ cong), rộng bằng vai.","Giữ khuỷu tay sát thân người, cuốn tạ lên ngang vai.","Giữ 1 giây ở điểm cao nhất.","Hạ tạ xuống từ từ về vị trí ban đầu."],"commonMistakes":["Nắm tạ quá hẹp hoặc quá rộng so với gờ cong thiết kế của thanh EZ.","Ưỡn lưng để lấy đà khi tạ nặng."],"quickTip":"Tay cầm chéo của thanh EZ giúp cổ tay thoải mái hơn tạ đòn thẳng với người bị đau cổ tay.","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/6999014/pexels-photo-6999014.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"cuon-ta-don-ghe-nghieng","name":"Cuốn tạ đơn ghế nghiêng","primaryMuscle":"tay_truoc","secondaryMuscles":[],"equipment":["ta_don","ghe_tap"],"difficulty":"intermediate","instructions":["Chỉnh ghế nghiêng khoảng 45-60 độ, ngồi tựa lưng, hai tay thả thẳng xuống.","Mỗi tay cầm tạ đơn, cuốn tạ lên ngang vai.","Giữ khuỷu tay cố định không đưa ra trước.","Hạ tạ xuống từ từ, cảm nhận căng ở tay trước tại điểm thấp nhất."],"commonMistakes":["Đưa khuỷu tay ra trước khi cuốn tạ, làm giảm biên độ căng cơ.","Chỉnh ghế nghiêng chưa đủ khiến bài tập giống cuốn tạ đứng thường."],"quickTip":"Tư thế ghế nghiêng kéo dài biên độ chuyển động, tạo cảm giác căng cơ rõ hơn ở điểm thấp.","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/7187900/pexels-photo-7187900.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"cuon-cap-dung","name":"Cuốn cáp đứng","primaryMuscle":"tay_truoc","secondaryMuscles":[],"equipment":["may_keo_xo"],"difficulty":"beginner","instructions":["Đứng đối diện máy cáp, nắm thanh tay cầm thấp rộng bằng vai.","Giữ khuỷu tay sát thân người, cuốn tay cầm lên ngang vai.","Giữ 1 giây ở điểm cao nhất.","Hạ tay cầm xuống từ từ, giữ lực căng liên tục."],"commonMistakes":["Đứng quá xa hoặc quá gần máy làm sai góc kéo.","Dùng đà thân người để cuốn tay cầm lên."],"quickTip":"Máy cáp giữ lực căng liên tục suốt bài, khác với tạ chỉ căng nhất ở giữa biên độ.","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/5327510/pexels-photo-5327510.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"cuon-ta-don-tap-trung","name":"Cuốn tạ đơn tập trung","primaryMuscle":"tay_truoc","secondaryMuscles":[],"equipment":["ta_don","ghe_tap"],"difficulty":"beginner","instructions":["Ngồi trên ghế, chân mở rộng, một tay chống lên đùi.","Tay còn lại cầm tạ, tựa khuỷu tay vào mặt trong đùi cùng bên.","Cuốn tạ lên ngang vai, giữ khuỷu tay cố định.","Hạ tạ xuống từ từ, đổi bên sau khi hết hiệp."],"commonMistakes":["Nhấc khuỷu tay khỏi đùi trong lúc cuốn tạ.","Dùng vai để hỗ trợ lực khi tạ quá nặng."],"quickTip":"Bài tập cô lập tốt nhất cho tay trước, phù hợp để hoàn thiện hình dáng cơ ở cuối buổi tập.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/8401861/pexels-photo-8401861.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"cuon-tay-bang-day-khang-luc","name":"Cuốn tay bằng dây kháng lực","primaryMuscle":"tay_truoc","secondaryMuscles":[],"equipment":["day_khang_luc"],"difficulty":"beginner","instructions":["Đứng lên giữa dây kháng lực, mỗi tay cầm một đầu dây.","Giữ khuỷu tay sát thân người, cuốn tay lên ngang vai.","Giữ 1 giây ở điểm cao nhất.","Hạ tay xuống từ từ, giữ dây luôn căng."],"commonMistakes":["Đứng lên dây quá lỏng làm giảm lực cản.","Đưa khuỷu tay ra trước trong lúc cuốn."],"quickTip":"Phù hợp tập tại nhà hoặc bổ sung cuối buổi khi đã hết tạ phù hợp.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/5714259/pexels-photo-5714259.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"keo-xa-nam-nguoc-hep-tay","name":"Kéo xà nắm ngược hẹp tay","primaryMuscle":"tay_truoc","secondaryMuscles":["lung_tren"],"equipment":["xa_ngang"],"difficulty":"advanced","instructions":["Nắm xà hẹp hơn vai, lòng bàn tay hướng vào người.","Treo người thẳng, siết bụng và tay trước.","Kéo người lên đến khi cằm qua xà, tập trung lực vào tay trước.","Hạ người xuống từ từ, kiểm soát tốc độ."],"commonMistakes":["Đung đưa thân người để lấy đà.","Không hạ hết tay ở điểm thấp nhất."],"quickTip":"Nắm hẹp và ngược làm tay trước tham gia nhiều hơn so với kéo xà nắm rộng.","suggestedRestSeconds":100,"imageUrl":"https://images.pexels.com/photos/17101707/pexels-photo-17101707.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"cuon-ta-don-nam-nguoc","name":"Cuốn tạ đòn nắm ngược","primaryMuscle":"tay_truoc","secondaryMuscles":["tay_sau"],"equipment":["ta_doi"],"difficulty":"intermediate","instructions":["Đứng thẳng, nắm tạ đòn rộng bằng vai, lòng bàn tay hướng xuống (nắm ngược).","Giữ khuỷu tay sát thân người, cuốn tạ lên ngang vai.","Giữ 1 giây ở điểm cao nhất.","Hạ tạ xuống từ từ về vị trí ban đầu."],"commonMistakes":["Dùng tạ quá nặng khiến cổ tay bị gập gây khó chịu.","Đung đưa thân người để lấy đà cuốn tạ lên."],"quickTip":"Bài này tác động nhiều vào cẳng tay và cơ brachialis, giúp tay trông dày hơn khi nhìn nghiêng.","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/14085138/pexels-photo-14085138.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-ta-don-sang-ngang","name":"Nâng tạ đơn sang ngang","primaryMuscle":"vai_giua","secondaryMuscles":[],"equipment":["ta_don"],"difficulty":"beginner","instructions":["Đứng thẳng, mỗi tay cầm tạ đơn hai bên đùi, khuỷu tay hơi cong.","Nâng hai tạ sang ngang đến khi ngang vai, lòng bàn tay hướng xuống.","Giữ 1 giây ở điểm cao nhất.","Hạ tạ xuống từ từ về vị trí ban đầu."],"commonMistakes":["Dùng đà thân người đung đưa để nâng tạ lên.","Nâng tạ cao quá vai gây căng khớp vai."],"quickTip":"Nâng tạ nhẹ với kỹ thuật chuẩn hiệu quả hơn tạ nặng nhưng sai form.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/6339688/pexels-photo-6339688.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-ta-don-sang-ngang-nghieng-nguoi","name":"Nâng tạ đơn sang ngang nghiêng người","primaryMuscle":"vai_giua","secondaryMuscles":[],"equipment":["ta_don"],"difficulty":"intermediate","instructions":["Đứng thẳng, nghiêng thân người sang một bên khoảng 15-20 độ.","Tay ở phía đối diện cầm tạ, nâng sang ngang đến ngang vai.","Giữ 1 giây ở điểm cao nhất, siết cơ vai giữa.","Hạ tạ xuống từ từ, hoàn thành hiệp rồi đổi bên."],"commonMistakes":["Nghiêng người quá nhiều làm mất tác dụng cô lập vai giữa.","Dùng lực thân trên hất tạ lên thay vì nâng bằng vai."],"quickTip":"Nghiêng người giúp giữ lực căng lên vai giữa suốt toàn bộ biên độ, kể cả điểm thấp nhất.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/3837388/pexels-photo-3837388.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-ta-sang-ngang-bang-day-khang-luc","name":"Nâng tạ sang ngang bằng dây kháng lực","primaryMuscle":"vai_giua","secondaryMuscles":[],"equipment":["day_khang_luc"],"difficulty":"beginner","instructions":["Đứng lên giữa dây kháng lực, mỗi tay cầm một đầu dây hai bên đùi.","Nâng hai tay sang ngang đến khi ngang vai.","Giữ 1 giây rồi hạ tay xuống từ từ.","Giữ thân người thẳng, không dùng đà."],"commonMistakes":["Đứng lên dây quá lỏng làm giảm lực cản ở điểm cuối.","Nâng tay cao hơn vai gây căng khớp."],"quickTip":"Dây kháng lực tạo lực cản tăng dần, giúp cơ vai giữa làm việc nhiều nhất ở đỉnh chuyển động.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/14925388/pexels-photo-14925388.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-ta-don-sang-ngang-ngoi","name":"Nâng tạ đơn sang ngang ngồi","primaryMuscle":"vai_giua","secondaryMuscles":[],"equipment":["ta_don","ghe_tap"],"difficulty":"beginner","instructions":["Ngồi trên ghế, lưng thẳng, mỗi tay cầm tạ đơn hai bên đùi.","Nâng hai tạ sang ngang đến khi ngang vai.","Giữ 1 giây ở điểm cao nhất.","Hạ tạ xuống từ từ, kiểm soát tốc độ."],"commonMistakes":["Ngồi không tựa thẳng lưng khiến dễ dùng đà thân trên.","Nâng tạ quá nhanh mất kiểm soát pha hạ xuống."],"quickTip":"Ngồi giúp loại bỏ hoàn toàn đà từ chân và hông, cô lập tốt vai giữa.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/5327477/pexels-photo-5327477.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"keo-ta-don-thang-dung","name":"Kéo tạ đòn thẳng đứng","primaryMuscle":"vai_giua","secondaryMuscles":["lung_tren"],"equipment":["ta_doi"],"difficulty":"intermediate","instructions":["Đứng thẳng, nắm tạ đòn rộng bằng vai trước đùi.","Kéo tạ thẳng lên dọc theo thân người đến ngang ngực, khuỷu tay hướng lên cao.","Giữ 1 giây ở điểm cao nhất.","Hạ tạ xuống từ từ về vị trí ban đầu."],"commonMistakes":["Kéo tạ quá cao gây chèn ép khớp vai.","Dùng đà thân người để kéo thay vì lực vai và tay."],"quickTip":"Nếu cảm thấy khó chịu ở vai, thử nắm tay rộng hơn hoặc giảm độ cao kéo tạ.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/4720793/pexels-photo-4720793.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"keo-ta-don-thang-dung-2","name":"Kéo tạ đơn thẳng đứng","primaryMuscle":"vai_giua","secondaryMuscles":["lung_tren"],"equipment":["ta_don"],"difficulty":"beginner","instructions":["Đứng thẳng, mỗi tay cầm tạ đơn trước đùi.","Kéo hai tạ thẳng lên dọc theo thân người đến ngang ngực.","Khuỷu tay hướng lên cao hơn cổ tay trong suốt chuyển động.","Hạ tạ xuống từ từ về vị trí ban đầu."],"commonMistakes":["Kéo tạ ra xa thân người thay vì sát người.","Nhún vai lên để lấy đà thay vì kéo bằng lực vai."],"quickTip":"Tạ đơn cho phép mỗi tay di chuyển theo quỹ đạo tự nhiên hơn tạ đòn.","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/32543165/pexels-photo-32543165.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-ta-sang-ngang-tren-may-cap","name":"Nâng tạ sang ngang trên máy cáp","primaryMuscle":"vai_giua","secondaryMuscles":[],"equipment":["may_keo_xo"],"difficulty":"intermediate","instructions":["Đứng nghiêng người bên cạnh máy cáp, tay gần máy cầm tay cầm thấp.","Kéo tay cầm sang ngang lên đến ngang vai, khuỷu tay hơi cong.","Giữ 1 giây ở điểm cao nhất, siết vai giữa.","Hạ tay cầm xuống từ từ, hoàn thành hiệp rồi đổi bên."],"commonMistakes":["Đứng quá gần máy làm giảm biên độ chuyển động.","Dùng lực thân trên xoay người để kéo tay cầm lên."],"quickTip":"Máy cáp giữ lực căng liên tục lên vai giữa, khác với tạ đơn chỉ căng nhất ở giữa biên độ.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/10754972/pexels-photo-10754972.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-ta-don-sang-ngang-tua-ghe-nghieng","name":"Nâng tạ đơn sang ngang tựa ghế nghiêng","primaryMuscle":"vai_giua","secondaryMuscles":[],"equipment":["ta_don","ghe_tap"],"difficulty":"intermediate","instructions":["Chỉnh ghế nghiêng khoảng 30 độ, nằm nghiêng một bên tựa vào ghế.","Tay trên cầm tạ đơn, nâng sang ngang đến ngang vai.","Giữ 1 giây ở điểm cao nhất.","Hạ tạ xuống từ từ, hoàn thành hiệp rồi đổi bên."],"commonMistakes":["Không tựa chắc vào ghế khiến thân người xoay theo tạ.","Nâng tạ bằng đà vai thay vì kiểm soát chậm rãi."],"quickTip":"Tư thế tựa ghế loại bỏ hoàn toàn khả năng dùng đà, giúp cô lập vai giữa tối đa.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/5327487/pexels-photo-5327487.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-ta-don-hinh-chu-y","name":"Nâng tạ đơn hình chữ Y","primaryMuscle":"vai_giua","secondaryMuscles":["vai_sau"],"equipment":["ta_don","ghe_tap"],"difficulty":"intermediate","instructions":["Chỉnh ghế nghiêng khoảng 45 độ, nằm sấp tựa ngực vào ghế.","Mỗi tay cầm tạ đơn nhẹ, duỗi thẳng xuống dưới.","Nâng hai tay chéo lên tạo hình chữ Y, lòng bàn tay hướng vào nhau.","Hạ tay xuống từ từ về vị trí ban đầu."],"commonMistakes":["Dùng tạ quá nặng khiến không nâng đúng hình chữ Y.","Nâng tay quá nhanh, không kiểm soát pha hạ xuống."],"quickTip":"Dùng tạ rất nhẹ vì đây là bài tập bổ trợ cho vai giữa và vai sau, không phải bài tập chính.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/6339681/pexels-photo-6339681.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-ta-don-chu-l-xoay-vai","name":"Nâng tạ đơn chữ L xoay vai","primaryMuscle":"vai_giua","secondaryMuscles":["vai_sau"],"equipment":["ta_don"],"difficulty":"advanced","instructions":["Đứng thẳng, một tay cầm tạ đơn nhẹ, khuỷu tay gập 90 độ sát thân người.","Nâng khuỷu tay sang ngang đến ngang vai, giữ góc gập 90 độ.","Xoay cẳng tay lên trên tạo hình chữ L.","Đảo ngược trình tự để hạ tay về vị trí ban đầu, đổi bên sau khi hết hiệp."],"commonMistakes":["Dùng tạ quá nặng khiến mất góc gập 90 độ chuẩn xác.","Thực hiện quá nhanh làm mất kiểm soát chuyển động phức tạp."],"quickTip":"Bài tập kỹ thuật cao, nên tập không tạ trước để nhớ đúng trình tự chuyển động.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/6550851/pexels-photo-6550851.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-ta-don-gap-nguoi-sau-vai","name":"Nâng tạ đơn gập người sau vai","primaryMuscle":"vai_sau","secondaryMuscles":["lung_tren"],"equipment":["ta_don"],"difficulty":"beginner","instructions":["Đứng cúi người về trước khoảng 45-90 độ, mỗi tay cầm tạ đơn thả tự nhiên.","Nâng hai tạ sang ngang ra sau, khuỷu tay hơi cong cố định.","Giữ 1 giây ở điểm cao nhất, siết vai sau.","Hạ tạ xuống từ từ về vị trí ban đầu."],"commonMistakes":["Đứng thẳng dần lên trong lúc nâng tạ, mất góc cúi cần thiết.","Dùng đà thân người hất tạ lên thay vì nâng bằng vai sau."],"quickTip":"Dùng tạ nhẹ hơn nhiều so với nâng tạ sang ngang thường vì vai sau là nhóm cơ nhỏ và yếu hơn.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/8874550/pexels-photo-8874550.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-ta-sau-vai-tren-ghe-nghieng-up-mat","name":"Nâng tạ sau vai trên ghế nghiêng úp mặt","primaryMuscle":"vai_sau","secondaryMuscles":["lung_tren"],"equipment":["ta_don","ghe_tap"],"difficulty":"intermediate","instructions":["Chỉnh ghế nghiêng khoảng 45 độ, nằm sấp tựa ngực vào ghế.","Mỗi tay cầm tạ đơn, duỗi thẳng xuống dưới.","Nâng hai tạ sang ngang ra sau đến ngang vai.","Hạ tạ xuống từ từ về vị trí ban đầu."],"commonMistakes":["Không tựa chắc ngực vào ghế khiến thân người dùng đà.","Nâng tạ quá cao lên phía trên đầu thay vì ngang vai."],"quickTip":"Tư thế tựa ghế loại bỏ hoàn toàn đà từ lưng, cô lập tối đa vai sau.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/3888350/pexels-photo-3888350.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"keo-cap-mat-face-pull","name":"Kéo cáp mặt (Face Pull)","primaryMuscle":"vai_sau","secondaryMuscles":["lung_tren"],"equipment":["may_keo_xo"],"difficulty":"intermediate","instructions":["Chỉnh ròng rọc máy cáp ngang mặt, gắn dây thừng.","Nắm hai đầu dây thừng, đứng lùi lại để dây căng.","Kéo dây về phía mặt, hai khuỷu tay mở rộng ra hai bên và cao hơn cổ tay.","Trả dây về vị trí ban đầu từ từ, giữ vai thả lỏng không nhún lên."],"commonMistakes":["Kéo dây xuống dưới cằm thay vì ngang mặt.","Nhún vai lên trong lúc kéo thay vì mở rộng khuỷu tay."],"quickTip":"Bài tập rất tốt để cân bằng vai sau với vai trước, nên đưa vào hầu hết các buổi tập.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/13865666/pexels-photo-13865666.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"cheo-ta-don-nam-rong-cui-nguoi","name":"Chèo tạ đơn nắm rộng cúi người","primaryMuscle":"vai_sau","secondaryMuscles":["lung_tren"],"equipment":["ta_don"],"difficulty":"intermediate","instructions":["Đứng cúi người 45 độ, mỗi tay cầm tạ đơn thả tự nhiên.","Kéo hai tạ lên cao ngang ngực, khuỷu tay mở rộng ra hai bên.","Giữ 1 giây ở điểm cao nhất, siết vai sau và lưng trên.","Hạ tạ xuống từ từ về vị trí ban đầu."],"commonMistakes":["Kéo khuỷu tay sát thân người thay vì mở rộng ra ngoài.","Đứng thẳng người dần lên khi mỏi."],"quickTip":"Nắm tay rộng và khuỷu tay mở ngang giúp nhắm nhiều hơn vào vai sau so với chèo tay hẹp.","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/17210050/pexels-photo-17210050.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-ta-sau-vai-bang-day-khang-luc","name":"Nâng tạ sau vai bằng dây kháng lực","primaryMuscle":"vai_sau","secondaryMuscles":[],"equipment":["day_khang_luc"],"difficulty":"beginner","instructions":["Cố định dây kháng lực phía trước ngang ngực, cúi người nhẹ về trước.","Mỗi tay cầm một đầu dây, tay duỗi thẳng về phía điểm cố định.","Kéo hai tay sang ngang ra sau, khuỷu tay hơi cong cố định.","Trả tay về vị trí ban đầu từ từ, giữ dây luôn căng."],"commonMistakes":["Đứng quá gần điểm cố định làm dây chùng ở điểm bắt đầu.","Gập khuỷu tay quá nhiều biến thành động tác kéo tay."],"quickTip":"Bài tập tiện lợi để bổ sung vai sau khi tập tại nhà không có tạ.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/4376713/pexels-photo-4376713.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"xoay-vai-ngoai-voi-day-khang-luc","name":"Xoay vai ngoài với dây kháng lực","primaryMuscle":"vai_sau","secondaryMuscles":[],"equipment":["day_khang_luc"],"difficulty":"beginner","instructions":["Cố định dây kháng lực ngang hông, đứng nghiêng người với dây ở bên cạnh.","Cầm dây bằng tay gần, khuỷu tay gập 90 độ ép sát thân người.","Xoay cẳng tay ra ngoài, giữ khuỷu tay cố định sát người.","Trả tay về vị trí ban đầu từ từ, đổi bên sau khi hết hiệp."],"commonMistakes":["Để khuỷu tay rời khỏi thân người trong lúc xoay.","Dùng dây có lực cản quá lớn làm mất kiểm soát chuyển động nhỏ."],"quickTip":"Bài tập nhẹ nhàng, phù hợp khởi động vai hoặc phục hồi chức năng khớp vai.","suggestedRestSeconds":45,"imageUrl":"https://images.pexels.com/photos/863977/pexels-photo-863977.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"keo-cap-cao-hinh-chu-y","name":"Kéo cáp cao hình chữ Y","primaryMuscle":"vai_sau","secondaryMuscles":["lung_tren"],"equipment":["may_keo_xo"],"difficulty":"advanced","instructions":["Đứng đối diện máy cáp, hai tay cầm hai tay cầm thấp bắt chéo nhau.","Kéo hai tay lên chéo cao tạo hình chữ Y, đồng thời hơi cúi người về trước.","Giữ 1 giây ở điểm cao nhất.","Trả tay về vị trí ban đầu từ từ."],"commonMistakes":["Dùng lực lưng dưới để kéo thay vì vai sau và lưng trên.","Chọn mức tạ quá nặng làm sai quỹ đạo chữ Y."],"quickTip":"Bài tập kỹ thuật cao, nên thử với mức tạ rất nhẹ trước để quen quỹ đạo.","suggestedRestSeconds":75,"imageUrl":"https://images.pexels.com/photos/22046780/pexels-photo-22046780.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-ta-don-chu-w","name":"Nâng tạ đơn chữ W","primaryMuscle":"vai_sau","secondaryMuscles":["lung_tren"],"equipment":["ta_don"],"difficulty":"intermediate","instructions":["Đứng cúi người nhẹ hoặc tựa ngực vào ghế nghiêng, mỗi tay cầm tạ đơn nhẹ.","Kéo hai tạ lên tạo hình chữ W, khuỷu tay gập và hướng ra sau.","Giữ 1 giây, siết vai sau và bả vai.","Hạ tạ xuống từ từ về vị trí ban đầu."],"commonMistakes":["Dùng tạ quá nặng khiến không giữ được hình chữ W chuẩn.","Kéo tạ quá nhanh mất kiểm soát chuyển động."],"quickTip":"Tập trung siết bả vai lại với nhau ở điểm cao nhất thay vì chỉ nâng tạ bằng tay.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/38576476/pexels-photo-38576476.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-ta-don-sau-vai-mot-tay-tua-ghe","name":"Nâng tạ đơn sau vai một tay tựa ghế","primaryMuscle":"vai_sau","secondaryMuscles":["lung_tren"],"equipment":["ta_don","ghe_tap"],"difficulty":"beginner","instructions":["Chống một tay và một gối lên ghế, lưng giữ song song sàn.","Tay còn lại cầm tạ, thả tự nhiên xuống dưới.","Nâng tạ sang ngang ra sau đến ngang vai.","Hạ tạ xuống từ từ, đổi bên sau khi hết hiệp."],"commonMistakes":["Xoay thân người theo tạ khi nâng lên.","Nâng tạ cao quá vai gây căng khớp."],"quickTip":"Tư thế chống ghế giúp cố định thân người tốt hơn đứng cúi tự do, phù hợp người mới tập vai sau.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/6353840/pexels-photo-6353840.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"day-vai-ta-don-dung","name":"Đẩy vai tạ đòn đứng","primaryMuscle":"vai_truoc","secondaryMuscles":["tay_sau"],"equipment":["ta_doi"],"difficulty":"intermediate","instructions":["Đứng chân rộng bằng vai, tạ đòn đặt ngang vai, lòng bàn tay hướng ra trước.","Siết bụng và mông để giữ ổn định cột sống.","Đẩy tạ thẳng lên trên đầu cho đến khi tay gần thẳng.","Hạ tạ xuống có kiểm soát về ngang vai."],"commonMistakes":["Ưỡn lưng dưới quá mức để đẩy tạ lên.","Đẩy tạ chếch ra trước thay vì thẳng trên đầu."],"quickTip":"Siết cơ mông và bụng như đang chuẩn bị bị đấm vào bụng để giữ thân người ổn định.","suggestedRestSeconds":120,"imageUrl":"https://images.pexels.com/photos/14591561/pexels-photo-14591561.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"day-vai-ta-don-dung-2","name":"Đẩy vai tạ đơn đứng","primaryMuscle":"vai_truoc","secondaryMuscles":["tay_sau"],"equipment":["ta_don"],"difficulty":"intermediate","instructions":["Đứng chân rộng bằng vai, mỗi tay cầm tạ đơn ngang vai, lòng bàn tay hướng ra trước.","Siết bụng, đẩy hai tạ thẳng lên trên đầu.","Hai tạ gần chạm nhau ở điểm cao nhất, không khóa cứng khuỷu tay.","Hạ tạ xuống từ từ về ngang vai."],"commonMistakes":["Dùng lực chân nhún để đẩy tạ lên (biến thành push press không chủ đích).","Để cổ tay gập ra sau làm mất lực đẩy."],"quickTip":"Tạ đơn cho phép vai di chuyển tự nhiên hơn tạ đòn, tốt cho người có vai nhạy cảm.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/7289370/pexels-photo-7289370.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"day-vai-ta-don-ngoi","name":"Đẩy vai tạ đơn ngồi","primaryMuscle":"vai_truoc","secondaryMuscles":["tay_sau"],"equipment":["ta_don","ghe_tap"],"difficulty":"beginner","instructions":["Ngồi trên ghế có tựa lưng, mỗi tay cầm tạ đơn ngang vai.","Lưng tựa chắc vào ghế, siết bụng.","Đẩy tạ thẳng lên trên đầu cho đến khi tay gần thẳng.","Hạ tạ xuống có kiểm soát về vị trí ban đầu."],"commonMistakes":["Không tựa lưng vào ghế khiến lưng dưới phải bù trừ.","Đẩy tạ ra trước thay vì thẳng lên trên."],"quickTip":"Ghế có tựa lưng giúp cô lập vai tốt hơn, phù hợp khi muốn tập nặng an toàn.","suggestedRestSeconds":90,"imageUrl":"https://images.pexels.com/photos/4164841/pexels-photo-4164841.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-ta-don-truoc-mat","name":"Nâng tạ đơn trước mặt","primaryMuscle":"vai_truoc","secondaryMuscles":[],"equipment":["ta_don"],"difficulty":"beginner","instructions":["Đứng thẳng, mỗi tay cầm tạ đơn trước đùi, lòng bàn tay hướng vào người.","Nâng một hoặc hai tạ thẳng lên trước đến ngang vai.","Giữ 1 giây ở điểm cao nhất, khuỷu tay hơi cong cố định.","Hạ tạ xuống từ từ về vị trí ban đầu."],"commonMistakes":["Dùng đà thân người đung đưa để nâng tạ lên.","Nâng tạ cao quá vai gây căng khớp."],"quickTip":"Có thể nâng luân phiên từng tay để giữ nhịp thở ổn định hơn khi nâng nặng.","suggestedRestSeconds":60,"imageUrl":"https://images.pexels.com/photos/4842732/pexels-photo-4842732.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"day-vai-ta-don-ngoi-2","name":"Đẩy vai tạ đòn ngồi","primaryMuscle":"vai_truoc","secondaryMuscles":["tay_sau"],"equipment":["ta_doi","ghe_tap"],"difficulty":"intermediate","instructions":["Ngồi trên ghế có tựa lưng, tạ đòn đặt ngang vai trên trước ngực.","Siết bụng, lưng tựa chắc vào ghế.","Đẩy tạ thẳng lên trên đầu cho đến khi tay gần thẳng.","Hạ tạ xuống có kiểm soát về ngang vai."],"commonMistakes":["Đẩy tạ chạm vào cằm hoặc mặt khi hạ xuống do góc ghế không phù hợp.","Không siết bụng khiến lưng dưới bị ép quá mức."],"quickTip":"Nhờ người hỗ trợ lấy tạ ở lần đầu nếu chưa quen tư thế ngồi đẩy vai.","suggestedRestSeconds":120,"imageUrl":"https://images.pexels.com/photos/17944268/pexels-photo-17944268.jpeg?auto=compress&cs=tinysrgb&fit=crop&w=800&h=600","isActive":true},{"id":"nang-ta-don-truoc-mat-luan-phien","name":"Nâng tạ đơn trước mặt luân phiên","primaryMuscle":"vai_truoc","secondaryMuscles":[],"equipment":["ta_don"],"difficulty":"beginner","instructions":["Đứng thẳng, mỗi tay cầm một tạ đơn trước đùi.","Nâng tạ bên phải lên ngang vai trong khi tay trái giữ nguyên.","Hạ tay phải xuống đồng thời nâng tay trái lên, luân phiên đều nhịp.","Giữ thân người thẳng, không đung đưa theo tạ."],"commonMistakes":["Xoay hông theo tay đang nâng để lấy đà.","Nâng tạ quá nhanh không kiểm soát